INSERT INTO `email_log` VALUES
(1,1048585,1,NULL,'2026-09-18 12:08:19',805306373,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"admin admin\" <sidalihadji00@gmail.com>','','','A new submission needs an editor to be assigned: \"Submission test\"','<p>Dear admin admin,</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=1\">\"Submission test\"</a><br /></p><p><b>Abstract</b></p><p>Testing Abstract </p><p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.</p>'),
(2,1048585,2,NULL,'2026-09-21 10:29:00',805306373,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"admin admin\" <sidalihadji00@gmail.com>','','','A new submission needs an editor to be assigned: \"Test\"','<p>Dear admin admin,</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=2\">\"Test\"</a><br /></p><p><b>Abstract</b></p><p>test</p><p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.</p>'),
(3,1048585,3,NULL,'2026-10-07 14:21:41',805306373,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"admin admin\" <sidalihadji00@gmail.com>','','','A new submission needs an editor to be assigned: \"Submission1\"','<p>Dear admin admin,</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">\"Submission1\"</a><br />Demo Author</p><p><b>Abstract</b></p><p>Abstract</p><p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.</p>'),
(4,1048585,3,NULL,'2026-10-07 14:21:41',805306373,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"Demo Editor\" <demo_editor@example.com>','','','A new submission needs an editor to be assigned: \"Submission1\"','<p>Dear Demo Editor,</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">\"Submission1\"</a><br />Demo Author</p><p><b>Abstract</b></p><p>Abstract</p><p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.</p>'),
(5,1048585,3,NULL,'2026-10-07 14:21:41',536870914,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"Demo Author\" <demo_author@example.com>','','','Thank you for your submission to Testing Journal','<p>Dear Demo Author,</p><p>Thank you for your submission to Testing Journal. We have received your submission, \"Submission1\", and a member of our editorial team will see it soon. You will be sent an email when an initial decision is made, and we may contact you for further information.</p><p>You can view your submission and track its progress through the editorial process at the following location:</p><p>Submission URL: http://localhost:8080/tj/en/dashboard/mySubmissions?workflowSubmissionId=3</p><p>If you have been logged out, you can login again with the username demo_author.</p><p>If you have any questions, please contact me from your <a href=\"http://localhost:8080/tj/en/dashboard/mySubmissions?workflowSubmissionId=3\">submission dashboard</a>.</p><p>Thank you for considering Testing Journal as a venue for your work.</p><br><br>—<br><p>This is an automated message from <a href=\"http://localhost:8080/tj\">Testing Journal</a>.</p>'),
(6,1048585,3,5,'2026-10-07 14:42:22',805306369,'\"Demo Editor\" <demo_editor@example.com>','\"Demo Author\" <demo_author@example.com>','','','Your submission has been sent for review','<p>Dear Demo Author,</p><p>I am pleased to inform you that an editor has reviewed your submission, \"Submission1\", and has decided to send it for peer review. An editor will identify qualified reviewers who will provide feedback on your submission.</p><p>This journal conducts double-anonymous peer review. The reviewers will not see any identifying information about you or your co-authors. Similarly, you will not know who reviewed your submission, and you will not hear from the reviewers directly. You will hear from us with feedback from the reviewers and information about the next steps.</p><p>Please note that sending the submission to peer review does not guarantee that it will be published. We will consider the reviewers\' recommendations before deciding to accept the submission for publication. You may be asked to make revisions and respond to the reviewers\' comments before a final decision is made.</p><p>If you have any questions, please contact me from your submission dashboard.</p><p><p>Demo Editor</p></p>'),
(7,1048585,3,5,'2026-10-07 14:43:17',1073741833,'\"Demo Editor\" <demo_editor@example.com>','\"Demo Reviewer1\" <demo_reviewer1@example.com>','','','Invitation to review','<p>Dear Demo Reviewer1,</p>\r\n<p>I believe that you would serve as an excellent reviewer for a submission to Testing Journal. The submission\'s title and abstract are below, and I hope that you will consider undertaking this important task for us.</p>\r\n<p>If you are able to review this submission, your review is due by 2026-11-03. You can view the submission, upload review files, and submit your review by logging into the journal site and following the steps at the link below.</p>\r\n<p><a href=\"http://localhost:8080/tj/en/reviewer/submission?submissionId=3\">Submission1</a></p>\r\n<p><strong>Abstract</strong></p>\r\n<p>Abstract</p>\r\n<p>Please <a href=\"http://localhost:8080/tj/en/reviewer/submission?submissionId=3\">accept or decline</a> the review by <strong>2026-11-03</strong>.</p>\r\n<p>You may contact me with any questions about the submission or the review process.</p>\r\n<p>Thank you for considering this request. Your help is much appreciated.</p>\r\n<p>Kind regards,</p>\r\n<p>Demo Editor</p>'),
(8,1048585,3,3,'2026-10-07 14:45:10',1073741829,'\"Demo Reviewer1\" <demo_reviewer1@example.com>','\"Demo Editor\" <demo_editor@example.com>','','','Review accepted: Demo Reviewer1 accepted review assignment for #3 Author — \"Submission1\"','<p>Dear Demo Editor,</p><p>Demo Reviewer1 has accepted the following review:</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">#3 Author — \"Submission1\"</a><br /><b>Type:</b> Anonymous Reviewer/Anonymous Author</p><p><b>Review Due:</b> 2026-11-03</p><p>Login to <a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">view all reviewer assignments</a> for this submission.</p><br><br>—<br>This is an automated message from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.'),
(9,1048585,3,5,'2026-10-07 14:45:54',1073741836,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"Demo Editor\" <demo_editor@example.com>','','','Review complete: Demo Reviewer1 recommends Accept Submission for #3 Author — \"Submission1\"','<p>Dear Demo Editor,</p><p>Demo Reviewer1 completed the following review:</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">#3 Author — \"Submission1\"</a><br /><b>Recommendation:</b> Accept Submission<br /><b>Type:</b> Anonymous Reviewer/Anonymous Author</p><p>Login to <a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=3\">view all files and comments</a> provided by this reviewer.</p>'),
(10,1048585,3,5,'2026-10-07 14:48:16',805306369,'\"Demo Editor\" <demo_editor@example.com>','\"Demo Author\" <demo_author@example.com>','','','Your submission has been accepted to Testing Journal','<p>Dear Demo Author,</p><p>I am pleased to inform you that we have decided to accept your submission without further revision. After careful review, we found your submission, Submission1, to meet or exceed our expectations. We are excited to publish your piece in Testing Journal and we thank you for choosing our journal as a venue for your work.</p><p>Your submission is now forthcoming in a future issue of Testing Journal and you are welcome to include it in your list of publications. We recognize the hard work that goes into every successful submission and we want to congratulate you on reaching this stage.</p><p>Your submission will now undergo copy editing and formatting to prepare it for publication.</p><p>You will shortly receive further instructions.</p><p>If you have any questions, please contact me from your <a href=\"http://localhost:8080/tj/en/dashboard/mySubmissions?workflowSubmissionId=3\">submission dashboard</a>.</p><p>Kind regards,</p><p>Demo Editor</p>'),
(11,1048585,3,5,'2026-10-07 14:48:16',1073741825,'\"Demo Editor\" <demo_editor@example.com>','\"Demo Reviewer1\" <demo_reviewer1@example.com>','','','Thank you for your review','<p>Dear Demo Reviewer1,</p>\n<p>Thank you for completing your review of the submission, \"Submission1\", for Testing Journal. We appreciate your time and expertise in contributing to the quality of the work that we publish. We have shared your comments with the authors, along with our other reviewers\' comments and the editor\'s decision.</p>\n<p>Based on the feedback we received, we have notified the authors of the following:</p>\n<p>We have chosen to accept this submission without revisions.</p>\n<p>Your recommendation was considered alongside the recommendations of other reviewers before coming to a decision. Occasionally the editor\'s decision may differ from the recommendation made by one or more reviewers. The editor considers many factors, and does not take these decisions lightly. We are grateful for our reviewers\' expertise and suggestions.</p>\n<p>It has been a pleasure to work with you as a reviewer for Testing Journal, and we hope to have the opportunity to work with you again in the future.</p>\n<p>Kind regards,</p>\n<p><p>Demo Editor</p></p>'),
(12,1048585,3,5,'2026-10-07 14:48:30',805306369,'\"Demo Editor\" <demo_editor@example.com>','\"Demo Author\" <demo_author@example.com>','','','Next steps for publishing your submission','<p>Dear Demo Author,</p><p>I am writing from Testing Journal to let you know that the editing of your submission, \"Submission1\", is complete. Your submission will now advance to the production stage, where the final galleys will be prepared for publication. We will contact you if we need any further assistance.</p><p>If you have any questions, please contact me from your <a href=\"http://localhost:8080/tj/en/dashboard/mySubmissions?workflowSubmissionId=3\">submission dashboard</a>.</p><p>Kind regards,</p><p>Demo Editor</p>'),
(13,1048585,4,NULL,'2026-10-07 17:27:41',805306373,'\"Mme Hamddad\" <sidalihadji00@gmail.com>','\"admin admin\" <sidalihadji00@gmail.com>','','','A new submission needs an editor to be assigned: \"Testing Submission\"','<p>Dear admin admin,</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"http://localhost:8080/tj/en/dashboard/editorial?workflowSubmissionId=4\">\"Testing Submission\"</a><br />Demo Author</p><p><b>Abstract</b></p><p>Lorem ipsum </p><p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"http://localhost:8080/tj/en\">Testing Journal</a>.</p>'),
