INSERT INTO `email_templates_default_data` VALUES
(1,'PASSWORD_RESET_CONFIRM','ar','تأكيد إعادة تعيين كلمة المرور','تأكيد إعادة تعيين كلمة المرور','لقد تلقينا طلباً لإعادة تعيين كلمة مرورك في الموقع {$siteTitle}.<br />\n<br />\nإن لم تكن أنت شخصياً من أرسل هذا الطلب، لطفاً تجاهل هذه الرسالة لتحتفظ بكلمة مرورك إلى الموقع دون تغيير. لو أردت إعادة تعيين كلمة مرورك، أنقر الرابط أدناه.<br />\n<br />\nأعد تعيين كلمة مروري: {$passwordResetUrl}<br />\n<br />\n{$siteContactName}'),
(2,'PASSWORD_RESET_CONFIRM','en','Password Reset Confirm','Password Reset Confirmation','We have received a request to reset your password for the {$siteTitle} web site.<br />\n<br />\nIf you did not make this request, please ignore this email and your password will not be changed. If you wish to reset your password, click on the below URL.<br />\n<br />\nReset my password: {$passwordResetUrl}<br />\n<br />\n{$siteContactName}'),
(3,'PASSWORD_RESET_CONFIRM','fr','Confirmation de la réinitialisation du mot de passe','Confirmation de la réinitialisation du mot de passe','Nous avons reçu une demande concernant la réinitialisation de votre mot de passe pour le site Web {$siteTitle}.<br />\n<br />\nSi vous n\'avez pas fait cette demande, veuillez ne pas tenir compte du présent message, votre mot de passe restera le même. Si vous voulez réinitialiser votre mot de passe, cliquer sur l\'URL et un nouveau mot de passe vous sera envoyé par courriel sous peu.<br />\n<br />\nRéinitialisation du mot de passe : {$passwordResetUrl}<br />\n<br />\n{$siteContactName}'),
(4,'USER_REGISTER','ar','تسجيل المستخدم','التسجيل في المجلة','{$recipientName}<br />\n<br />\nأنت الآن مسجل كمستخدم ضمن {$contextName}. قمنا بتضمين اسم الدخول وكلمة المرور في هذه الرسالة، كونهما ضروريان لمتابعة كل الأعمال والوظائف في موقع المجلة. يمكنك المطالبة في أي وقت بإزالة اسمك من قائمة المستخدمين المسجلين عبر مراسلتي.<br />\n<br />\nاسم الدخول: {$recipientUsername}<br />\nكلمة المرور: {$password}<br />\n<br />\nشكراً لك.<br />\n{$signature}'),
(5,'USER_REGISTER','en','User Created','Journal Registration','{$recipientName}<br />\n<br />\nYou have now been registered as a user with {$contextName}. We have included your username and password in this email, which are needed for all work with this journal through its website. At any point, you can ask to be removed from the journal\'s list of users by contacting me.<br />\n<br />\nUsername: {$recipientUsername}<br />\nPassword: {$password}<br />\n<br />\nThank you,<br />\n{$signature}'),
(6,'USER_REGISTER','fr','Création de l\'utilisateur·rice','Inscription d\'un nouvel utilisateur','{$recipientName}<br />\n<br />\nVous êtes désormais inscrit en tant qu\'utilisateur pour {$contextName}. Veuillez conserver précieusement votre nom d\'utilisateur et votre mot de passe. Vous en aurez besoin pour toutes vos interactions avec la revue. À n\'importe quel moment, vous pouvez demander à être retiré de la liste des utilisateurs de la revue en me contactant.<br />\n<br />\nNom d\'utilisateur : {$recipientUsername}<br />\nMot de passe : {$password}<br />\n<br />\nMerci,<br />\n{$signature}'),
(7,'USER_VALIDATE_CONTEXT','ar','التحقق من البريد الالكتروني (التسجيل في المجلة)','تأكيد صحة حسابك','{$recipientName}<br />\n<br />\nقمت بإنشاء حساب في {$contextName}، لكن قبل شروعك باستعماله، عليك تأكيد عنوان بريدك الالكتروني، وكل ما عليك القيام به الآن، اتباع الرابط أدناه:<br />\n<br />\n{$activateUrl}<br />\n<br />\nشكراً لك.<br />\n{$contextSignature}'),
(8,'USER_VALIDATE_CONTEXT','en','Validate Email (Journal Registration)','Validate Your Account','{$recipientName}<br />\n<br />\nYou have created an account with {$contextName}, but before you can start using it, you need to validate your email account. To do this, simply follow the link below:<br />\n<br />\n{$activateUrl}<br />\n<br />\nThank you,<br />\n{$contextSignature}'),
(9,'USER_VALIDATE_CONTEXT','fr','Validez l\'adresse courriel (enregistrement de la revue)','Valider votre compte','{$recipientName}<br />\n<br />\nVous avez créé un compte avec {$contextName}, mais avant de pouvoir commencer à l\'utiliser, vous devez valider votre courriel. Pour ce faire, suivre simplement le lien ci-dessous :<br />\n<br />\n{$activateUrl}<br />\n<br />\nMerci,<br />\n{$contextSignature}'),
(10,'USER_VALIDATE_SITE','ar','التحقق من البريد الالكتروني (الموقع)','تأكيد صحة حسابك','{$recipientName}<br />\n<br />\nلقد أنشأت حسابًا في {$siteTitle}، ولكن قبل أن يتسنى لك استعماله، أنت بحاجة إلى تأكيد صحة عنوان بريدك الالكتروني. للقيام بذلك، فقط عليك اتباع الرابط أدناه:<br />\n<br />\n{$activateUrl}<br />\n<br />\nشكرًا لك،<br />\n{$siteSignature}'),
(11,'USER_VALIDATE_SITE','en','Validate Email (Site)','Validate Your Account','{$recipientName}<br />\n<br />\nYou have created an account with {$siteTitle}, but before you can start using it, you need to validate your email account. To do this, simply follow the link below:<br />\n<br />\n{$activateUrl}<br />\n<br />\nThank you,<br />\n{$siteSignature}'),
(12,'USER_VALIDATE_SITE','fr','Valider le courriel (site)','Valider votre compte','{$recipientName},<br />\n<br />\nVous avez créé un compte dans {$siteTitle}. Avant de pouvoir commencer à l\'utiliser, il nous faut d\'abord valider votre adresse de courriel. Pour ce faire, vous n\'avez qu\'à suivre le lien ci-dessous :<br />\n<br />\n{$activateUrl}<br />\n<br />\nMerci,<br />\n{$siteSignature}'),
(13,'REVIEWER_REGISTER','ar','تسجيل المحكم','التسجيل بصفة محكم في {$contextName}','<p>عزيزي {$recipientName},</p><p>في ضوء ما هو معروف عنك من خبرة، سنحت لنا الظروف بتسجيل اسمك ضمن قاعدة بياناتنا للمحكمين في موقع {$contextName}. هذا الأمر لا يترتب عليه أي مستوى من الإلتزام من جهتك، بل ببساطة، يمكننا من التواصل معك بشأن إحتمالية تحكيم بعض طلبات النشر التي ترد مجلتنا. فيما لو تمت دعوتك مستقبلاً لغرض التحكيم، ستكون لك فرصة الاطلاع على عنوان المؤلَّف وملخصه، وستكون صاحب الرأي بشأن الموافقة على تلك الدعوة أو الاعتذار عنها. فضلاً عن ذلك، بإمكانك دوماً المطالبة برفع اسمك من قائمة المحكمين هذه.</p><p>نحن نزودك باسم الدخول وكلمة المرور الخاصين بك، واللذين يتيحان لك القيام بكل الفعاليات المتعلقة بعملك ضمن موقعنا. فقد ترغب، على سبيل المثال، بتحديث بيانات ملفك الشخصي وتضمين المجالات العلمية التي يهمك التحكيم فيها.</p><p>اسم الدخول: {$recipientUsername}<br />كلمة المرور: {$password}</p><p>شكراً لك.</p>{$signature}'),
(14,'REVIEWER_REGISTER','en','Reviewer Register','Registration as Reviewer with {$contextName}','<p>Dear {$recipientName},</p><p>In light of your expertise, we have registered your name in the reviewer database for {$contextName}. This does not entail any form of commitment on your part, but simply enables us to approach you with a submission to possibly review. On being invited to review, you will have an opportunity to see the title and abstract of the paper in question, and you\'ll always be in a position to accept or decline the invitation. You can also ask at any point to have your name removed from this reviewer list.</p><p>We are providing you with a username and password, which is used in all interactions with the journal through its website. You may wish, for example, to update your profile, including your reviewing interests.</p><p>Username: {$recipientUsername}<br />Password: {$password}</p><p>Thank you,</p>{$signature}'),
(15,'REVIEWER_REGISTER','fr','Enregistrement de l\'évaluateur·rice','Inscription en tant que rapporteur de {$contextName}','<p>Bonjour {$recipientName},</p><p>Compte tenu de votre expertise, nous avons pris l\'initiative d\'inscrire votre nom dans la base de données des évaluateurs-trices de la revue {$contextName}. Cela ne vous engage d\'aucune façon, mais nous permet simplement de solliciter vos services pour l\'évaluation d\'une soumission. Si vous êtes invité-e à effectuer une évaluation, vous recevrez le titre et le résumé de l\'article en question, et serez toujours libre d\'accepter ou de refuser une telle invitation. À tout moment, il vous est également possible de demander à ce que votre nom soit retiré de la liste des évaluateurs-trices.</p><p>Nous vous acheminons un nom d\'utilisateur-trice et un mot de passe, car tous deux sont requis pour tout échange avec la revue via son site Web. Vous pouvez, par exemple, si vous le souhaitez, effectuer la mise à jour de votre profil, y compris vos domaines d\'intérêt en matière d\'évaluation.</p><p>Nom d\'utilisateur-trice : {$recipientUsername}<br />Mot de passe : {$password}</p><p>Merci,</p>{$signature}'),
(16,'ISSUE_PUBLISH_NOTIFY','ar','إشعار إصدار العدد','توًا صدر العدد: {$issueIdentification} من المجلة {$contextName}','<p>عزيزي {$recipientName}،</p><p>يسعدنا أن نعلن عن إصدار <a href=\"{$issueUrl}\">{$issueIdentification}</a> من{$contextName}. نحن ندعوكم إلى قراءة هذا العمل ومشاركته مع مجتمعكم العلمي.</p><p>جزيل الشكر للمؤلفين، المحكمين، والمحررين للإسهاماتهم القيمة، ولقرائنا لاهتمامهم المستمر بأعمالنا.</p><div>{$issueToc}</div><p>مع الاعتزاز،</p>{$signature}'),
(17,'ISSUE_PUBLISH_NOTIFY','en','Issue Published Notify','Just published: {$issueIdentification} of {$contextName}','<p>Dear {$recipientName},</p><p>We are pleased to announce the publication of <a href=\"{$issueUrl}\">{$issueIdentification}</a> of {$contextName}.  We invite you to read and share this work with your scholarly community.</p><p>Many thanks to our authors, reviewers, and editors for their valuable contributions, and to our readers for your continued interest.</p><div>{$issueToc}</div><p>Thank you,</p>{$signature}'),
(18,'ISSUE_PUBLISH_NOTIFY','fr','Notification de numéro paru','Parution du dernier numéro : {$issueIdentification} de la revue {$contextName}','<p>Cher lecteur, chère lectrice,</p><p>La revue {$contextName} a le plaisir de vous annoncer la publication de son dernier numéro : <a href=\"{$issueUrl}\">{$issueIdentification}</a>. Nous vous invitons à lire et partager son contenu avec vos collègues et la communauté académique.</p><p>Nous remercions vivement nos auteurs et autrices, évaluateurs et évaluatrices ainsi que les rédacteurs et rédactrices pour leurs précieuses contributions à cet ouvrage, ainsi que notre cher public pour son intérêt constant.</p><p>Cordialement,</p>{$signature}'),
(19,'SUBMISSION_ACK','ar','إقرار طلب التقديم','شكرًا على تقديم طلبك إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>شكراً على تقديمك إلى {$contextName}. لقد تلقينا طلب تقديمك، \"{$submissionTitle}\"، وسيقوم أحد أعضاء هيئة التحرير بالنظر فيه قريبًا. ستتلقى بريدًا الكترونيًا عند اتخاذ قرار أولي بشأنه، وقد نتواصل معك بصدد المزيد من المعلومات.</p><p>يمكنك معاينة طلبك ومتابعة سير تقدمه في مراحل التحرير في الموقع الآتي:</p><p>رابط التقديم: {$authorSubmissionUrl}</p><p>إذا خرجت من الموقع، بإمكانك معاودة تسجيل الدخول باستعمال اسم المستخدم {$recipientUsername}.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>شكراً على اعتبارك {$contextName} جديرة بعملك.</p>{$contextSignature}'),
(20,'SUBMISSION_ACK','en','Submission Confirmation','Thank you for your submission to {$contextName}','<p>Dear {$recipientName},</p><p>Thank you for your submission to {$contextName}. We have received your submission, \"{$submissionTitle}\", and a member of our editorial team will see it soon. You will be sent an email when an initial decision is made, and we may contact you for further information.</p><p>You can view your submission and track its progress through the editorial process at the following location:</p><p>Submission URL: {$authorSubmissionUrl}</p><p>If you have been logged out, you can login again with the username {$recipientUsername}.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>Thank you for considering {$contextName} as a venue for your work.</p>{$contextSignature}'),
(21,'SUBMISSION_ACK','fr','Confirmation de soumission','Merci pour votre soumission à {$contextName}','<p>{$recipientName},</p><p>Nous vous remercions d\'avoir soumis à {$contextName} le manuscrit intitulé « {$submissionTitle} », qui sera bientôt examinée. Dès qu\'une première décision aura été prise, vous recevrez un courriel et nous pourrons vous contacter pour de plus amples informations.</p><p>Grâce à notre système de gestion en ligne, vous pourrez suivre votre soumission tout au long du processus d\'édition en accédant à l\'adresse suivante :</p><p>URL du manuscrit : {$submissionUrl}</p><p>Si vous avez été déconnecté, vous pouvez vous connecter à nouveau avec le nom d\'utilisateur {$recipientUsername}</p><p>Si vous avez des questions, veuillez nous contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Nous vous remercions d\'avoir pensé à nous pour la publication de vos travaux.</p>{$contextSignature}'),
(22,'SUBMISSION_ACK_NOT_USER','ar','تأكيد طلب التقديم (المؤلفون الآخرون)','تأكيد طلب التقديم','<p>عزيزنا {$recipientName}،</p><p>لقد تمت تسميتك بمثابة مؤلف مشارك في طلب تقديم إلى {$contextName}. مقدم الطلب، {$submitterName}، أعطانا التفاصيل الآتية:</p><p>\"{$submissionTitle}\"<br>{$authorsWithAffiliation}</p><p>إن كان أي من تلك التفاصل غير صحيح، أو ليست لديك الرغبة في تسميتك كمؤلف مشارك في هذا العمل، يرجى التواصل معي.</p><p>شكرًا لاعتبارك هذه المجلة مضمارًا لعملك.</p><p>أطيب التحايا،</p>{$contextSignature}'),
(23,'SUBMISSION_ACK_NOT_USER','en','Submission Confirmation (Other Authors)','Submission confirmation','<p>Dear {$recipientName},</p><p>You have been named as a co-author on a submission to {$contextName}. The submitter, {$submitterName}, provided the following details:</p><p>\"{$submissionTitle}\"<br>{$authorsWithAffiliation}</p><p>If any of these details are incorrect, or you do not wish to be named on this submission, please contact me.</p><p>Thank you for considering {$contextName} as a venue for your work.</p><p>Kind regards,</p>{$contextSignature}'),
(24,'SUBMISSION_ACK_NOT_USER','fr','Confirmation de soumission (autres auteur·e·s)','Accusé de réception de la soumission','<p>{$recipientName},</p><p>Votre nom figure en tant que co-auteur·e d\'une soumission à {$contextName}. Le·La déposant·e, {$submitterName}, a fourni les informations suivantes :</p><p>{$submissionTitle}<br>{$authorsWithAffiliation}</p><p>Si l\'une de ces informations est incorrecte ou si vous ne souhaitez pas figurer dans cette soumission, veuillez me contacter.</p><p>Nous vous remercions d\'avoir choisi {$contextName} pour publier votre travail.</p><p>Cordialement,</p>{$contextSignature}'),
(25,'EDITOR_ASSIGN','ar','المحرر تم تعيينه','لقد تم تعيينك كمحرر لطلب التقديم الموجه إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>طلب التقديم الآتي قد تمت إحالته إليك لتقوم بإجراءات التحرير المتعلقة به.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>الملخص</b></p>{$submissionAbstract}<p>إذا وجدت بأن طلب التقديم ذي صلة بـ {$contextName}، يرجى تمريره إلى مرحلة التحكيم عبر اختيار \"الإرسال إلى التحكيم\" ومن ثم قم بتعيين المحكمين عبر النقر على \"إضافة محكم\".</p><p>إذا كان طلب التقديم غير مناسب لهذه المجلة، يرجى رفض الطلب.</p><p>شكرًا لك مقدمًا.</p><p>أطيب التحايا،</p>{$contextSignature}'),
(26,'EDITOR_ASSIGN','en','Editor Assigned','You have been assigned as an editor on a submission to {$contextName}','<p>Dear {$recipientName},</p><p>The following submission has been assigned to you to see through the editorial process.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Abstract</b></p>{$submissionAbstract}<p>If you find the submission to be relevant for {$contextName}, please forward the submission to the review stage by selecting \"Send to Review\" and then assign reviewers by clicking \"Add Reviewer\".</p><p>If the submission is not appropriate for this journal, please decline the submission.</p><p>Thank you in advance.</p><p>Kind regards,</p>{$contextSignature}'),
(27,'EDITOR_ASSIGN','fr','Editeur·rice désigné·e','Vous avez été assigné.e en tant que rédacteur.trice d\'une soumission de la revue {$contextName}','<p>{$recipientName},</p><p>La soumission suivante vous a été assignée pour le suivi du processus éditorial.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Résumé</b></p>{$submissionAbstract}<p>Si vous jugez la soumission pertinente pour la revue {$contextName}, veuillez la transmettre à l\'étape d\'évaluation en sélectionnant « Envoyer en évaluation» et en désignant des évaluateur.trice.s en cliquant sur « Ajouter un.e évaluateur.trice ».</p><p>Si la soumission n\'est pas appropriée pour cette revue, veuillez la décliner.</p><p>Je vous remercie d\'avance.</p><p>Cordialement,</p>{$contextSignature}'),
(28,'REVIEW_CANCEL','ar','محكم تم إلغاء تعيينه','إلغاء إلتماس التحكيم','<p> عزيزي {$recipientName}،</p><p>مؤخرًا، إلتمسنا منكم تحكيم طلب تقديم معنون إلى {$contextName}. لقد قررنا إلغاء إلتماسنا لكم بتحكيم المؤلَّف الموسوم، {$submissionTitle}.</p><p>نحن نعتذر عن أي إزعاج قد يسببه ذلك لحضرتكم، ونأمل التواصل معكم مستقبلاً فيما يتعلق بتحكيم طلبات التقديم المرسلة إلى هذه المجلة.</p><p>إن كانت لديكم أي استفسارات، لطفاً، إتصلوا بي.</p>{$signature}'),
(29,'REVIEW_CANCEL','en','Reviewer Unassign','Request for Review Cancelled','<p>Dear {$recipientName},</p><p>Recently, we asked you to review a submission to {$contextName}. We have decided to cancel the request for you to reivew the submission, {$submissionTitle}.</p><p>We apologize any inconvenience this may cause you and hope that we will be able to call on you to assist with this journal\'s review process in the future.</p><p>If you have any questions, please contact me.</p>{$signature}'),
(30,'REVIEW_CANCEL','fr','Evaluateur( trice) plus attribué(e)','Annulation de la demande d\'évaluation','<p>{$recipientName},</p><p>Récemment, nous vous avons demandé d\'évaluer une soumission pour {$contextName}. Nous avons décidé d\'annuler notre demande que vous évaluiez le manuscrit intitulé « {$submissionTitle} ».</p><p>Nous sommes désolés des inconvénients que cela pourrait vous causer et nous espérons que nous pourrons compter sur votre collaboration pour un autre projet.</p><p>Si vous avez des questions, n\'hésitez pas à nous contacter.</p>{$signature}'),
(31,'REVIEW_REINSTATE','ar','محكم تمت إعادته','هل لا زال بإمكانك تحكيم أي شيء لصالح {$contextName}؟','<p>عزيزي {$recipientName}،</p><p>ألغينا مؤخرًا إلتماسنا لكم لتحكيم طلب التقديم الموسوم {$submissionTitle}، لصالح {$contextName}. لقد قمنا بمراجعة ذلك القرار وكلنا أمل بأنكم لا تزالون قادرين على تولي مهمة التحكيم.</p><p>إذا كنتم راغبين بإبداء العون لنا في عملية التحكيم لهذه المجلة، بإمكانكم <a href=\"{$reviewAssignmentUrl}\">تسجيل الدخول إلى موقع المجلة</a>لمعاينة طلب التقديم، رفع ملفات التحكيم، وتسليم نتيجته.</p><p>إذا كانت لديكم أي استفسارات، يرجى التواصل معي.</p><p>أطيب التحايا،</p>{$signature}'),
(32,'REVIEW_REINSTATE','en','Reviewer Reinstate','Can you still review something for {$contextName}?','<p>Dear {$recipientName},</p><p>We recently cancelled our request for you to review a submission, {$submissionTitle}, for {$contextName}. We\'ve reversed that decision and we hope that you are still able to conduct the review.</p><p>If you are able to assist with this submission\'s review, you can <a href=\"{$reviewAssignmentUrl}\">login to the journal</a> to view the submission, upload review files, and submit your review request.</p><p>If you have any questions, please contact me.</p><p>Kind regards,</p>{$signature}'),
(33,'REVIEW_REINSTATE','fr','Evaluateur(trice) réintégré(e)','Êtes-vous encore en mesure d\'évaluer des travaux pour la revue {$contextName} ?','<p>{$recipientName},</p><p>Nous avons récemment annulé notre demande vous demandant d\'évaluer la soumission, {$submissionTitle}, pour la revue {$contextName}. Nous sommes revenus sur cette décision et nous espérons que vous êtes toujours en mesure d\'effectuer l\'évaluation.</p><p>Si vous êtes en mesure d\'aider au processus d\'évaluation de cette revue, vous pouvez vous <a href=\"{$reviewAssignmentUrl}\">connecter au site de la revue</a> pour voir la soumission, téléverser les fichiers d\'évaluation ainsi que soumettre votre évaluation.</p><p>Si vous avez des questions, n\'hésitez pas à nous contacter,</p><p>Cordialement,</p>{$signature}'),
(34,'REVIEW_RESEND_REQUEST','ar','إعادة إرسال إلتماس التحكيم للمحكم','إلتماس تحكيمك مرة أخرى لـ {$contextName}','<p>عزيزي {$recipientName}،</p><p>لقد رفضت مؤخرًا طلبنا لتحكيم طلب التقديم، \"{$submissionTitle}\"، بشأن {$contextName}. إنني أكتب لأقف على ما إذا كنت مستعدًا لإجراء التحكيم على أي حال.</p><p>سنكون ممتنين لك إذا أجريت هذا التحكيم، ولكننا نتفهم موقفك إذا لم يكن بإمكانك القيام به في الوقت الحالي. بكل الأحوال، <a href=\"{$reviewAssignmentUrl}\">إقبل إلتماسنا أو أرفضه</a> حتى {$responseDueDate}، ليتسنى لنا البحث عن محكم بديل.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي.</p><p>أطيب التحايا،</p>{$signature}'),
(35,'REVIEW_RESEND_REQUEST','en','Resend Review Request to Reviewer','Requesting your review again for {$contextName}','<p>Dear {$recipientName},</p><p>Recently, you declined our request to review a submission, \"{$submissionTitle}\", for {$contextName}. I\'m writing to see if you are able to conduct the review after all.</p><p>We would be grateful if you\'re able to perform this review, but we understand if that is not possible at this time. Either way, please <a href=\"{$reviewAssignmentUrl}\">accept or decline the request</a> by {$responseDueDate}, so that we can find an alternate reviewer.</p><p>If you have any questions, please contact me.</p><p>Kind regards,</p>{$signature}'),
(36,'REVIEW_RESEND_REQUEST','fr','Envoyer à nouveau la demande d\'évaluation à l\'évaluateur·rice','Demande de réévaluation pour {$contextName}','<p>{$recipientName},</p><p>Récemment, vous avez décliné notre demande d\'évaluation d\'une soumission, « {$submissionTitle} », pour {$contextName}. Je vous écris pour savoir s\'il est possible que vous reveniez sur votre décision.</p><p>Nous vous serions très reconnaissants si vous étiez en mesure d\'accepter cette évaluation, mais nous comprenons également que vous soyez dans l\'impossibilité de le faire en ce moment. Quoi qu\'il en soit, pourriez-vous <a href=\"{$reviewAssignmentUrl}\">accepter ou décliner notre demande</a> avant le {$responseDueDate} ?</p><p>Si vous avez des questions, n\'hésitez pas à me contacter.</p><p>Cordialement,</p>{$signature}'),
(37,'REVIEW_REQUEST','ar','إلتماس التحكيم','دعوة لتحكيم مؤلَّف','<p>عزيزي {$recipientName}،</p><p>كلي ثقة بأنك ستكون محكماً متميزاً للمؤلَّف المقدم إلى {$contextName}. إن عنوانه وملخصه مبينان أدناه، وأنا أرجو أنك ستأخذ على عاتقك إنجاز هذه المهمة لمجلتنا.</p><p>إن كنت قادرًا على تحكيم طلب التقديم هذا، فإن الموعد النهائي لتسليم تحكيمك هو {$reviewDueDate}. يمكنك معاينة طلب التقديم ورفع ملفات التحكيم وتسليمه عبر تسجيل دخولك إلى موقع المجلة ومتابعة الخطوات المذكورة في الرابط الآتي.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>الملخص</b></p>{$submissionAbstract}<p>يرجى <a href=\"{$reviewAssignmentUrl}\">قبول تولي المهمة أو رفضها</a> في موعد أقصاه <b>{$responseDueDate}</b>.</p><p>يمكنك التواصل معي بشأن أي استفسارات متعلقة بطلب التقديم وعملية تحكيمه.</p><p>نشكر لك اهتمامك بالتماسنا هذا. مساعدتك لنا نقابلها ببالغ التقدير.</p><p>أطيب التحايا،</p>{$signature}'),
(38,'REVIEW_REQUEST','en','Review Request','Invitation to review','<p>Dear {$recipientName},</p><p>I believe that you would serve as an excellent reviewer for a submission  to {$contextName}. The submission\'s title and abstract are below, and I hope that you will consider undertaking this important task for us.</p><p>If you are able to review this submission, your review is due by {$reviewDueDate}. You can view the submission, upload review files, and submit your review by logging into the journal site and following the steps at the link below.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please <a href=\"{$reviewAssignmentUrl}\">accept or decline</a> the review by <b>{$responseDueDate}</b>.</p><p>You may contact me with any questions about the submission or the review process.</p><p>Thank you for considering this request. Your help is much appreciated.</p><p>Kind regards,</p>{$signature}'),
(39,'REVIEW_REQUEST','fr','Demande d\'évaluation','Invitation à évaluer un article','<p>Cher {$recipientName},</p><p>Nous pensons que vous seriez un excellent évaluateur pour une soumission à {$contextName}. Le titre et le résumé de la soumission sont ci-dessous, et nous espérons que vous envisagerez de réaliser cette tâche importante pour nous.</p><p>Si vous êtes en mesure d\'évaluer cette soumission, votre évaluation est due pour le {$reviewDueDate}. Vous pouvez consulter la soumission, télécharger les fichiers d\'évaluation et soumettre votre évaluation en vous connectant au site de la revue et en suivant les étapes via le lien ci-dessous.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Résumé</b></p>{$submissionAbstract}<p>Veuillez <a href=\"{$reviewAssignmentUrl}\">accepter ou refuser</a> l\'évaluation avant le <b>{$responseDueDate}</b>.</p><p>Vous pouvez nous contacter pour toute question concernant la soumission ou le processus d\'évaluation.</p><p>Merci de considérer cette demande. Votre aide est très appréciée.</p><p>Cordialement,</p>{$signature}'),
(40,'REVIEW_REQUEST_SUBSEQUENT','ar','متابعة إلتماس التحكيم','إلتماس تحكيم مؤلَّف منقح','<p>عزيزي {$recipientName}،</p><p>شكرًا لقيامك بتحكيم <a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a>. لقد أخذ المؤلفون آراء المحكمين بنظر الاعتبار وقدموا نسخة منقحة من عملهم. إنني أراسل بشأن رغبتكم بإجراء جولة تحكيم مناظر ثانية لطلب التقديم هذا.</p><p>إن كنتم قادرين على تولي مهمة التحكيم هذه، فتسليم التحكيم موعده النهائي هو {$reviewDueDate}. يمكنكم <a href=\"{$reviewAssignmentUrl}\">اتباع خطوات التحكيم</a> لمعاينة طلب التقديم، رفع ملفات التحكيم، وتسليم ملاحظاته.<p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p>الملخص</p>{$submissionAbstract}<p>يرجى <a href=\"{$reviewAssignmentUrl}\">قبول تولي المهمة أو رفضها</a> في موعد أقصاه<b>{$responseDueDate}</b>.</p><p>رجاءً لا تترددوا في مراسلتي بشأن أي استفسارات تتعلق بطلب التقديم أو عملية تحكيمه.</p><p>نشكر لكم أخذكم لالتماسنا هذا بنظر الاعتبار. مساعدتكم نقابلها ببالغ التقدير.</p><p>أطيب التحايا،</p>{$signature}'),
(41,'REVIEW_REQUEST_SUBSEQUENT','en','Review Request Subsequent','Request to review a revised submission','<p>Dear {$recipientName},</p><p>Thank you for your review of <a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a>. The authors have considered the reviewers\' feedback and have now submitted a revised version of their work. I\'m writing to ask if you would conduct a second round of peer review for this submission.</p><p>If you are able to review this submission, your review is due by {$reviewDueDate}. You can <a href=\"{$reviewAssignmentUrl}\">follow the review steps</a> to view the submission, upload review files, and submit your review comments.<p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please <a href=\"{$reviewAssignmentUrl}\">accept or decline</a> the review by <b>{$responseDueDate}</b>.</p><p>Please feel free to contact me with any questions about the submission or the review process.</p><p>Thank you for considering this request. Your help is much appreciated.</p><p>Kind regards,</p>{$signature}'),
(42,'REVIEW_REQUEST_SUBSEQUENT','fr','Demande d\'évaluation ultérieure','Demande d\'évaluation d\'un article révisé','<p>Cher ou chère {$recipientName},</p><p>Merci beaucoup pour votre évaluation de <a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a>. Les auteur/ices ont pris en compte vos commentaires et ont maintenant soumis une version révisée de leur travail. Nous voudrions savoir si vous acceptez de participer à un nouveau tour d\'évaluation.</p><p>Si vous êtes en mesure d\'évaluer cette soumission, votre retour est attendu pour le {$reviewDueDate}. Vous pouvez <a href=\"{$reviewAssignmentUrl}\">suivre les étapes d\'évaluation</a> afin de consulter la soumission, télécharger les fichiers d\'évaluation et soumettre vos commentaires.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Résumé</b></p>{$submissionAbstract}<p>Veuillez <a href=\"{$reviewAssignmentUrl}\">accepter ou refuser</a> l\'évaluation avant le <b>{$responseDueDate}</b>.</p><p>N\'hésitez pas à nous contacter pour toute question concernant la soumission ou le processus d\'évaluation.</p><p>Merci de considérer cette demande. Votre aide est très appréciée.</p><p>Cordialement,</p>{$signature}'),
(43,'REVIEW_RESPONSE_OVERDUE_AUTO','ar','تجاوز موعد تسليم التحكيم (مؤتمت)','هل ستتمكن من تحكيم هذا المؤلَّف لنا؟','<p>عزيزي {$recipientName}</p><p>هذه الرسالة هي تذكير آلي من جانب {$contextName} بشأن إلتماسنا لحضرتكم تحكيم طلب التقديم الموسوم \"{$submissionTitle}.\"</p><p>أنت تتلقى هذه الرسالة لأننا لم نتسلم منك حتى الآن تأكيدًا بقبول أو رفض توليك لمهمة تحكيمه.</p><p>يرجى إعلامنا ما إذا كنت قادرًا على التكفل بهذا التحكيم عبر استعمال برنامجنا لإدارة طلبات التقديم لتوثيق قبولك أو رفضك.</p><p>إن كنت قادرًا على تولي مهمة التحكيم هذه، فتسليمك للتحكيم موعده النهائي هو {$reviewDueDate}. يمكنك اتباع خطوات التحكيم لمعاينة طلب التقديم، رفع ملفات التحكيم، وتسليم ملاحظات تحكيمك.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>الملخص</b></p>{$submissionAbstract}<p>رجاءً لا تتردد في مراسلتي بشأن أي استفسارات تتعلق بطلب التقديم أو عملية تحكيمه.</p><p>نشكر لك أخذك لالتماسنا هذا بنظر الاعتبار. مساعدتك نقابلها ببالغ التقدير.</p><p>أطيب التحايا،</p>{$contextSignature}'),
(44,'REVIEW_RESPONSE_OVERDUE_AUTO','en','Review Response Overdue (Automated)','Will you be able to review this for us?','<p>Dear {$recipientName},</p><p>This email is an automated reminder from {$contextName} in regards to our request for your review of the submission, \"{$submissionTitle}.\"</p><p>You are receiving this email because we have not yet received a confirmation from you indicating whether or not you are able to undertake the review of this submission.</p><p>Please let us know whether or not you are able to undertake this review by using our submission management software to accept or decline this request.</p><p>If you are able to review this submission, your review is due by {$reviewDueDate}. You can follow the review steps to view the submission, upload review files, and submit your review comments.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please feel free to contact me with any questions about the submission or the review process.</p><p>Thank you for considering this request. Your help is much appreciated.</p><p>Kind regards,</p>{$contextSignature}'),
(45,'REVIEW_RESPONSE_OVERDUE_AUTO','fr','Réponse à l\'évaluation en retard (automatisée)','Seriez-vous en mesure d\'évaluer ce manuscrit pour nous ?','<p>Cher {$recipientName},</p><p>Ce courriel est un rappel automatique de {$contextName} concernant notre demande d\'évaluation de la soumission, \"{$submissionTitle}.\"</p><p>Vous recevez ce courriel parce que nous n\'avons pas encore reçu de confirmation de votre part indiquant si vous êtes en mesure de réaliser l\'évaluation de cette soumission.</p><p>Veuillez nous faire savoir si vous êtes en mesure de réaliser cette évaluation en utilisant notre logiciel de gestion des soumissions pour accepter ou refuser cette demande.</p><p>Si vous êtes en mesure d\'évaluer cette soumission, votre évaluation est due pour le {$reviewDueDate}. Vous pouvez suivre les étapes d\'évaluation pour consulter la soumission, télécharger les fichiers d\'évaluation et soumettre vos commentaires.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a></p><p><b>Résumé</b></p>{$submissionAbstract}<p>N\'hésitez pas à nous contacter pour toute question concernant la soumission ou le processus d\'évaluation.</p><p>Merci de considérer cette demande. Votre aide est très appréciée.</p><p>Cordialement,</p>{$contextSignature}'),
(46,'REVIEW_CONFIRM','ar','تأكيد التحكيم','التحكيم تم قبوله: {$reviewerName} قد وافق على مهمة تحكيم #{$submissionId} {$authorsShort} — \"{$submissionTitle}\"','<p>عزيزي {$recipientName}،</p><p>{$reviewerName} قد وافق على التحكيم الآتي:</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — \"{$submissionTitle}\"</a><br /><b>النوع:</b> {$reviewMethod}</p><p><b>موعد استيجاب التحكيم:</b> {$reviewDueDate}</p><p>سجل دخولك <a href=\"{$submissionUrl}\">لمعاينة كل مهام المحكم</a> لطلب التقديم هذا.</p><br><br>—<br>هذه رسالة مؤتمتة من <a href=\"{$contextUrl}\">{$contextName}</a>.'),
(47,'REVIEW_CONFIRM','en','Review Confirm','Review accepted: {$reviewerName} accepted review assignment for #{$submissionId} {$authorsShort} — \"{$submissionTitle}\"','<p>Dear {$recipientName},</p><p>{$reviewerName} has accepted the following review:</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — \"{$submissionTitle}\"</a><br /><b>Type:</b> {$reviewMethod}</p><p><b>Review Due:</b> {$reviewDueDate}</p><p>Login to <a href=\"{$submissionUrl}\">view all reviewer assignments</a> for this submission.</p><br><br>—<br>This is an automated message from <a href=\"{$contextUrl}\">{$contextName}</a>.'),
(48,'REVIEW_CONFIRM','fr','Confirmation de l\'évaluation','Évaluation acceptée : {$reviewerName} a accepté l\'évaluation de #{$submissionId} {$authorsShort} — {$submissionTitle}','<p>{$recipientName},</p><p>{$reviewerName} a accepté l\'évaluation suivante :</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — {$submissionTitle}</a><br /><b>Type :</b> {$reviewMethod}</p><p><b>Évaluation prévue avant le {$reviewDueDate}</b> </p><p>Connectez-vous pour <a href=\"{$submissionUrl}\">voir toutes les tâches d\'évaluation</a> liées à cette soumission.</p><br><br>—<br>Ceci est un message automatique de<a href=\"{$contextUrl}\">{$contextName}</a>.'),
(49,'REVIEW_DECLINE','ar','رفض التحكيم','غير قادر على التحكيم','أعزائي المحررون:<br />\n<br />\nأخشى أنني حالياً غير متفرغ لتحكيم المؤلَّف الموسوم &quot;{$submissionTitle},&quot; والمرسل إلى {$contextName}. أشكر لكم إعتمادكم عليَّ وأرجو التواصل معي في وقت آخر.<br />\n<br />\n{$senderName}'),
(50,'REVIEW_DECLINE','en','Review Decline','Unable to Review','Editors:<br />\n<br />\nI am afraid that at this time I am unable to review the submission, &quot;{$submissionTitle},&quot; for {$contextName}. Thank you for thinking of me, and another time feel free to call on me.<br />\n<br />\n{$senderName}'),
(51,'REVIEW_DECLINE','fr','Refus de l\'évaluation','Refus d\'évaluation','Rédacteurs :<br />\n<br />\nPour le moment, il m\'est impossible d\'évaluer la soumission intitulée « {$submissionTitle} » pour {$contextName}. Je vous remercie d\'avoir pensé à moi. N\'hésitez pas à communiquer avec moi pour un autre projet.<br />\n<br />\n{$senderName}'),
(52,'REVIEW_ACK','ar','إقرار التحكيم','شكرًا على تحكيمك','<p>عزيزنا {$recipientName}،</p>\n<p>نشكر إكمالك لتحكيم المؤلَّف الموسوم، \"{$submissionTitle}\"، لصالح {$contextName}. إننا نقدر وقتكم وخبراتكم التي شاركتموها في ترصين الأعمال التي تنشرها مجلتنا.</p>\n<p>لقد كان لنا الشرف أن نعمل معكم كمحرر لصالح {$contextName}، ونأمل أن تتاح لنا فرصة العمل معكم مرة أخرى مستقبلاً.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>'),
(53,'REVIEW_ACK','en','Review Acknowledgement','Thank you for your review','<p>Dear {$recipientName},</p>\n<p>Thank you for completing your review of the submission, \"{$submissionTitle}\", for {$contextName}. We appreciate your time and expertise in contributing to the quality of the work that we publish.</p>\n<p>It has been a pleasure to work with you as a reviewer for {$contextName}, and we hope to have the opportunity to work with you again in the future.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>'),
(54,'REVIEW_ACK','fr','Accusé de réception de l\'évaluation','Merci pour votre évaluation','<p>{$recipientName},</p>\n<p>Nous vous remercions d\'avoir évalué la soumission « {$submissionTitle} » pour {$contextName}. Nous apprécions le temps et l\'expertise que vous avez consacrés à la qualité des travaux que nous publions.</p>\n<p>Nous sommes heureux de cette collaboration et espérons pouvoir travailler à nouveau avec vous à l\'avenir.</p>\n<p>Cordialement,</p>\n<p>{$signature}</p>'),
(55,'REVIEW_REMIND','ar','تذكير التحكيم','تذكير يلتمس إكمال التحكيم','<p>عزيزي {$recipientName}،</p><p>هذا مجرد تذكير لجنابكم الكريم بشأن تحكيمكم للمؤلَّف الموسوم \"{$submissionTitle}\"، لصالح {$contextName}. نحن نأمل الحصول منكم على هذا التحكيم في موعد أقصاه {$reviewDueDate} ونرجو أن نتلقاه منكم حالماً تكونوا جاهزين لإرساله.</p><p>يمكنكم <a href=\"{$reviewAssignmentUrl}\">تسجيل الدخول إلى موقع المجلة</a> وتتبع خطوات التحكيم لمعاينة طلب التقديم، رفع ملفات التحكيم، وتسليم ملاحظاتكم بشأنه.</p><p>إذا كنتم بحاجة إلى تمديد الموعد، يرجى التواصل معي. إنني أتطلع إلى ردكم الكريم.</p><p>شكرًا مقدمًا مع أطيب التحايا،</p>{$signature}'),
(56,'REVIEW_REMIND','en','Review Reminder','A reminder to please complete your review','<p>Dear {$recipientName},</p><p>Just a gentle reminder of our request for your review of the submission, \"{$submissionTitle},\" for {$contextName}. We were expecting to have this review by {$reviewDueDate} and we would be pleased to receive it as soon as you are able to prepare it.</p><p>You can <a href=\"{$reviewAssignmentUrl}\">login to the journal</a> and follow the review steps to view the submission, upload review files, and submit your review comments.</p><p>If you need an extension of the deadline, please contact me. I look forward to hearing from you.</p><p>Thank you in advance and kind regards,</p>{$signature}'),
(57,'REVIEW_REMIND','fr','Rappel d\'évaluation','Un rappel pour vous demander de bien vouloir terminer votre évaluation','<p>Bonjour {$recipientName},</p><p>Ceci est un petit rappel concernant notre demande d\'évaluation de la soumission « {$submissionTitle} » pour la revue {$contextName}. Nous espérions recevoir votre évaluation avant le {$reviewDueDate}. Nous serions heureux de la recevoir dès que possible.</p><p>Vous pouvez vous <a href=\"{$reviewAssignmentUrl}\">connecter au site de la revue</a> et suivre les étapes d\'évaluation afin de consulter le texte, soumettre votre fichier d\'évaluation ainsi que vos commentaires. </p><p>Si vous avez besoin de plus de temps, contactez-nous. Nous vous remercions par avance.</p><p>Cordialement,</p>{$signature}'),
(58,'REVIEW_REMIND_AUTO','ar','تذكير التحكيم (مؤتمت)','تذكير يلتمس إكمال تحكيمك','<p>عزيزي {$recipientName}:</p><p>رسالة البريد الالكتروني هذه هي تذكير آلي من {$contextName} بشأن إلتماسنا لجنابكم الكريم تحكيم طلب التقديم الموسوم، \"{$submissionTitle}\".</p><p>كنا نأمل الحصول منكم على هذا التحكيم في موعد أقصاه {$reviewDueDate} ونرجو أن نتلقاه منكم حالماً تكونوا جاهزين لإرساله.</p><p>يرجى <a href=\"{$reviewAssignmentUrl}\">تسجيل الدخول إلى موقع المجلة</a> وتتبع خطوات التحكيم لمعاينة طلب التقديم، رفع ملفات التحكيم، وتسليم ملاحظاتكم بشأنه.</p><p>إذا كنتم بحاجة إلى تمديد الموعد، يرجى التواصل معي. إنني أتطلع إلى ردكم الكريم.</p><p>شكرًا مقدمًا مع أطيب التحايا،</p>{$contextSignature}'),
(59,'REVIEW_REMIND_AUTO','en','Review Reminder (Automated)','A reminder to please complete your review','<p>Dear {$recipientName}:</p><p>This email is an automated reminder from {$contextName} in regards to our request for your review of the submission, \"{$submissionTitle}.\"</p><p>We were expecting to have this review by {$reviewDueDate} and we would be pleased to receive it as soon as you are able to prepare it.</p><p>Please <a href=\"{$reviewAssignmentUrl}\">login to the journal</a> and follow the review steps to view the submission, upload review files, and submit your review comments.</p><p>If you need an extension of the deadline, please contact me. I look forward to hearing from you.</p><p>Thank you in advance and kind regards,</p>{$contextSignature}'),
(60,'REVIEW_REMIND_AUTO','fr','Rappel d\'évaluation (automatisé)','Un rappel automatique pour vous demander de bien vouloir terminer votre évaluation','<p>{$recipientName},</p><p>Ceci est un rappel automatisé de la revue {$contextName} concernant notre demande d\'évaluation de la soumission « {$submissionTitle} ». Nous espérions votre évaluation pour le {$reviewDueDate} et nous serons ravis de la recevoir dès que possible.</p><p>S\'il vous plait, <a href=\"{$reviewAssignmentUrl}\">connectez-vous à la revue</a> et suivez les étapes d\'évaluation afin de consulter le texte et soumettre votre fichier d\'évaluation ainsi que vos commentaires.</p><p>Si vous avez besoin d\'un délai supplémentaire, n\'hésitez pas à nous contacter.</p><p>Nous vous remercions</p><p>Cordialement, </p>{$contextSignature}'),
(61,'REVIEW_COMPLETE','ar','التحكيم تم إكماله','إكتمل التحكيم: {$reviewerName} يوصي {$reviewRecommendation} بشأن #{$submissionId} {$authorsShort} — \"{$submissionTitle}\"','<p>عزيزي {$recipientName}،</p><p>{$reviewerName} قد أكمل التحكيم الآتي:</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — \"{$submissionTitle}\"</a><br /><b>التوصية:</b> {$reviewRecommendation}<br /><b>النوع:</b> {$reviewMethod}</p><p>سجل دخولك إلى <a href=\"{$submissionUrl}\">لمعاينة كل الملفات والتعليقات</a> التي قدمها هذا المحكم.</p>'),
(62,'REVIEW_COMPLETE','en','Review Completed','Review complete: {$reviewerName} recommends {$reviewRecommendation} for #{$submissionId} {$authorsShort} — \"{$submissionTitle}\"','<p>Dear {$recipientName},</p><p>{$reviewerName} completed the following review:</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — \"{$submissionTitle}\"</a><br /><b>Recommendation:</b> {$reviewRecommendation}<br /><b>Type:</b> {$reviewMethod}</p><p>Login to <a href=\"{$submissionUrl}\">view all files and comments</a> provided by this reviewer.</p>'),
(63,'REVIEW_COMPLETE','fr','Évaluation terminée','Évaluation terminée : {$reviewerName} recommande {$reviewRecommendation} pour #{$submissionId} {$authorsShort} — {$submissionTitle}','<p>{$recipientName},</p><p>{$reviewerName} a terminé l\'évaluation suivante :</p><p><a href=\"{$submissionUrl}\">#{$submissionId} {$authorsShort} — {$submissionTitle}</a><br /><b>Recommendation :</b> {$reviewRecommendation}<br /><b>Type:</b> {$reviewMethod}</p><p>Connectez-vous pour <a href=\"{$submissionUrl}\">consulter tous les fichiers et commentaires</a> de cette évaluation.</p>'),
(64,'REVIEW_EDIT','ar','التحكيم تم تعديله','مهمة تحكيمك قد تغيرت لـ {$contextName}','<p>عزيزي {$recipientName}،</p><p>أجرى أحد المحررين تغييرًا لمهمة تحكيمك لـ {$contextName}. يرجى مراجعتكم للتفاصيل أدناه ثم أيلغونا إذا كانت لديكم أي استفسارات.</p><p><a href=\"{$reviewAssignmentUrl}\">\"{$submissionTitle}\"</a><br /><b>النوع:</b> {$reviewMethod}<br /><b>إقبله أو أرفض بموعد أقصاه:</b> {$responseDueDate}<br /><b>تسليم التحكيم بموعد أقصاه:</b> {$reviewDueDate}</p><p>يمكنكم تسجيل الدخول <a href=\"{$reviewAssignmentUrl}\">إكمال هذا التحكيم</a> في أي وقت.</p>'),
(65,'REVIEW_EDIT','en','Review Edited','Your review assignment has been changed for {$contextName}','<p>Dear {$recipientName},</p><p>An editor has made changes to your review assignment for {$contextName}. Please review the details below and let us know if you have any questions.</p><p><a href=\"{$reviewAssignmentUrl}\">\"{$submissionTitle}\"</a><br /><b>Type:</b> {$reviewMethod}<br /><b>Accept or Decline By:</b> {$responseDueDate}<br /><b>Submit Review By:</b> {$reviewDueDate}</p><p>You can login to <a href=\"{$reviewAssignmentUrl}\">complete this review</a> at any time.</p>'),
(66,'REVIEW_EDIT','fr','Évaluation modifiée','Votre tâche d\'évaluation pour {$contextName} a été modifiée','<p>{$recipientName},</p><p>Des modifications ont été apportées à notre demande d\'évaluation pour {$contextName}. Veuillez lire les détails ci-dessous et nous faire part de vos questions.</p><p><a href=\"{$reviewAssignmentUrl}\">{$submissionTitle}</a><br /><b>Type :</b> {$reviewMethod}<br />Réponse attendue avant le <b>{$responseDueDate}</b> <br />Évaluation prévue avant le <b>{$reviewDueDate}</b></p><p>Vous pouvez vous connecter à tout moment pour <a href=\"{$reviewAssignmentUrl}\">compléter cette évaluation</a>.</p>'),
(67,'EDITOR_DECISION_ACCEPT','ar','طلب التقديم مقبول','لقد تم قبول طلب تقديمك في {$contextName}','<p>عزيزي {$recipientName}،</p><p>يسعدني إبلاغك بأننا قررنا قبول طلب تقديمك بدون المزيد من التنقيحات. بعد المراجعة المتأنية، وجدنا بأن طلب تقديمك، {$submissionTitle}، يلبي توقعاتنا أو يفوقها. نحن متحمسون لنشر عملك في {$contextName} ونشكرك على اختيار مجلتنا محلاً لإظهار عملك.</p><p>طلب تقديمك من المتوقع نشره في عدد قادم من {$contextName} ويسعدنا أن تضمنه في قائمة أعمالك المنشورة. نحن نميز الجهد المبذول وراء كل طلب تقديم ناجح ونود تهنئتك على بلوغ هذه المرحلة.</p><p>سيخضع طلب تقديمك الآن إلى التدقيق الإملائي والتنسيق لتحضيره للنشر.</p><p>ستتلقى قريبًا المزيد من التعليمات.</p><p>إن كانت لديك أي أسئلة، يرجى التواصل معي من <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب تقديمك</a>.</p><p>أطيب التحايا،</p>{$signature}'),
(68,'EDITOR_DECISION_ACCEPT','en','Submission Accepted','Your submission has been accepted to {$contextName}','<p>Dear {$recipientName},</p><p>I am pleased to inform you that we have decided to accept your submission without further revision. After careful review, we found your submission, {$submissionTitle}, to meet or exceed our expectations. We are excited to publish your piece in {$contextName} and we thank you for choosing our journal as a venue for your work.</p><p>Your submission is now forthcoming in a future issue of {$contextName} and you are welcome to include it in your list of publications. We recognize the hard work that goes into every successful submission and we want to congratulate you on reaching this stage.</p><p>Your submission will now undergo copy editing and formatting to prepare it for publication.</p><p>You will shortly receive further instructions.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>Kind regards,</p>{$signature}'),
(69,'EDITOR_DECISION_ACCEPT','fr','Soumission acceptée','Décision du rédacteur','<p>Cher {$recipientName},</p><p>Nous avons le plaisir de vous informer que nous avons décidé d\'accepter votre soumission sans révision supplémentaire. Après un examen attentif, nous avons trouvé que votre soumission, {$submissionTitle}, répondait ou dépassait nos attentes. Nous sommes ravis de publier votre travail dans {$contextName} et nous vous remercions d\'avoir choisi notre revue pour présenter votre travail.</p><p>Votre soumission paraîtra prochainement dans un futur numéro de {$contextName} et vous êtes invité à l\'inclure dans votre liste de publications. Nous reconnaissons le travail acharné nécessaire à chaque soumission réussie et nous tenons à vous féliciter pour avoir atteint cette étape.</p><p>Votre soumission va maintenant être soumise à la révision linguistique et à la mise en forme en vue de sa publication.</p><p>Vous recevrez prochainement des instructions supplémentaires.</p><p>Si vous avez des questions, veuillez nous contacter depuis votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Cordialement,</p>{$signature}'),
(70,'EDITOR_DECISION_SEND_TO_EXTERNAL','ar','مُرسل إلى التحكيم','طلب تقديمك قد أُرسل للتحكيم','<p>عزيزنا {$recipientName}،</p><p>يسرني أبلاغكم بأن أحد المحررين قد راجع طلب تقديمكم، \"{$submissionTitle}\"، وقرر إرساله للتحكيم المناظر. سيقوم المحرر بتحديد المحكمين الذين سيعطوننا إفاداتهم بشأن طلبكم.</p><p>{$reviewTypeDescription} ستتلقون منا رسائل لاحقة فيها ملاحظات المحكمين ومعلومات عن الخطوات اللاحقة.</p><p>يرجى ملاحظة أن إرسال طلب التقديم إلى التحكيم المناظر لا يعني بالضرورة قبوله للنشر. سنأخذ بنظر الاعتبار توصيات المحكمين قبل اتخاذنا قرار الموافقة على النشر. قد تتم مطالبتكم بإجراء تنقيحات والرد على تعليقات المحكمين قبل التوصل إلى القرار النهائي.</p><p>إذا كانت لديكم أي أسئلة، يرجى التواصل معي عبر دفة القيادة الخاصة بطلب تقديمكم.</p><p>{$signature}</p>'),
(71,'EDITOR_DECISION_SEND_TO_EXTERNAL','en','Sent to Review','Your submission has been sent for review','<p>Dear {$recipientName},</p><p>I am pleased to inform you that an editor has reviewed your submission, \"{$submissionTitle}\", and has decided to send it for peer review. An editor will identify qualified reviewers who will provide feedback on your submission.</p><p>{$reviewTypeDescription} You will hear from us with feedback from the reviewers and information about the next steps.</p><p>Please note that sending the submission to peer review does not guarantee that it will be published. We will consider the reviewers\' recommendations before deciding to accept the submission for publication. You may be asked to make revisions and respond to the reviewers\' comments before a final decision is made.</p><p>If you have any questions, please contact me from your submission dashboard.</p><p>{$signature}</p>'),
(72,'EDITOR_DECISION_SEND_TO_EXTERNAL','fr','Envoyé pour évaluation externe','Votre soumission a été envoyée pour évaluation','<p>{$recipientName},</p><p>J\'ai le plaisir de vous informer que votre soumission, « {$submissionTitle} », va être envoyée pour évaluation par les pairs. Des évaluateur·rice·s qualifié·e·s fourniront des commentaires sur votre soumission.</p><p>{$reviewTypeDescription} Nous vous communiquerons ces commentaires et des informations sur les prochaines étapes.</p><p>Veuillez noter que l\'envoi de la soumission à évaluation par les pairs ne garantit pas qu\'elle sera publiée. Nous tiendrons compte des recommandations des évaluateur·rice·s avant de décider d\'accepter la soumission pour publication. Il se peut que nous vous demandions d\'apporter des modifications et de répondre aux commentaires des évaluateurs avant de prendre une décision.</p><p>Si vous avez des questions, veuillez me contacter à partir de votre tableau de bord de soumission.</p><p>{$signature}</p>'),
(73,'EDITOR_DECISION_SEND_TO_PRODUCTION','ar','مُرسل إلى الإنتاج','الخطوات اللاحقة لنشر طلب تقديمكم','<p>عزيزنا {$recipientName}،</p><p>إنني أراسلكم من {$contextName} لإبلاغكم بأن عملية تحرير طلب تقديمكم \"{$submissionTitle}\"، قد انتهت. سيذهب عملكم الآن إلى مرحلة الإنتاج، حيث سيجري تحضير الألواح الطباعية للنشر. سنتواصل معكم إذا كانت لدينا حاجة إلى مساعدتكم.</p><p>إذا كانت لديكم أي أسئلة، يرجى التواصل معي من <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>أطيب التحايا،</p>{$signature}'),
(74,'EDITOR_DECISION_SEND_TO_PRODUCTION','en','Sent to Production','Next steps for publishing your submission','<p>Dear {$recipientName},</p><p>I am writing from {$contextName} to let you know that the editing of your submission, \"{$submissionTitle}\", is complete. Your submission will now advance to the production stage, where the final galleys will be prepared for publication. We will contact you if we need any further assistance.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>Kind regards,</p>{$signature}'),
(75,'EDITOR_DECISION_SEND_TO_PRODUCTION','fr','Envoyé en production','Prochaines étapes pour la publication de votre soumission','<p>{$recipientName},</p><p>Je vous écris pour vous informer que l\'édition de votre soumission, « {$submissionTitle} », est terminée. Elle va maintenant passer à l\'étape de la production, où les dernières épreuves seront préparées avant publication. Nous vous contacterons si nous avons besoin de votre aide.</p><p>Si vous avez des questions, veuillez me contacter à partir de votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Cordialement,</p>{$signature}'),
(76,'EDITOR_DECISION_REVISIONS','ar','التنقيحات تمت المطالبة بها','طلب تقديمكم قد تمت مراجعته ونحن نحثكم على تقديم التنقيحات','<p>عزيزي {$recipientName}،</p><p>طلب تقديمك \"{$submissionTitle}\" قد تمت مراجعته ونحن نشجعك على تقديم التنقيحات التي تتناول ملاحظات المحكمين. سيراجع أحد المحررين تلك التنقيحات وإذا ما وجدها كافية لتلبية ما هو مطلوب، فقد يتم قبول عملك للنشر.</p><p>ملاحظات المحكمين موجودة عند نهاية هذه الرسالة. يرجى الاستجابة لكل نقطة مذكورة في ملاحظات المحكمين وأعط وصفًا للتغيرات التي أجريتها. إذا وجدت أيًا من ملاحظات المحكمين غير مبررة أو غير مناسبة، يرجى توضيح وجهة نظرك.</p><p>عندما تكمل تنقيحاتك، بإمكانك رفع المستندات المعدلة مع إجابتك بشأن ملاحظات المحكمين من خلال <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>. إذا خرجت من الموقع، بإمكانك معاودة تسجيل الدخول باستعمال اسم المستخدم {$recipientUsername}.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>نحن نتطلع لتلقي طلب تقديمك المنقح.</p><p>أطيب التحايا،</p>{$signature}<hr><p>الملاحظات الآتية تم تلقيها من طرف المحكمين.</p>{$allReviewerComments}'),
(77,'EDITOR_DECISION_REVISIONS','en','Revisions Requested','Your submission has been reviewed and we encourage you to submit revisions','<p>Dear {$recipientName},</p><p>Your submission \"{$submissionTitle}\" has been reviewed and we would like to encourage you to submit revisions that address the reviewers\' comments. An editor will review these revisions and if they address the concerns adequately, your submission may be accepted for publication.</p><p>The reviewers\' comments are included at the bottom of this email. Please respond to each point in the reviewers\' comments and identify what changes you have made. If you find any of the reviewer\'s comments to be unjustified or inappropriate, please explain your perspective.</p><p>When you have completed your revisions, you can upload revised documents along with your response to the reviewers\' comments at your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>. If you have been logged out, you can login again with the username {$recipientUsername}.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>We look forward to receiving your revised submission.</p><p>Kind regards,</p>{$signature}<hr><p>The following comments were received from reviewers.</p>{$allReviewerComments}'),
(78,'EDITOR_DECISION_REVISIONS','fr','Révisions demandées','Votre soumission a été évaluée et nous vous invitons à soumettre des révisions','<p>{$recipientName},</p><p>Votre soumission « {$submissionTitle} » a été évaluée et nous vous invitons à soumettre des révisions qui répondent aux commentaires des évaluateur·rice·s. Après examen de ces révisions, si elles répondent de manière adéquate aux questions soulevées, votre soumission peut être acceptée pour publication.</p><p>Les commentaires des évaluations figurent au bas de ce courriel. Veuillez répondre à chaque point et indiquer les modifications que vous avez apportées. Si vous estimez que l\'un des commentaires n\'est pas justifié, veuillez expliquer votre point de vue.</p><p>Lorsque vous aurez terminé vos révisions, vous pourrez télécharger les documents révisés ainsi que votre réponse aux commentaires des évaluateur·rice·s sur votre <a href=\"{$authorSubmissionUrl}\"> tableau de bord de soumission</a>. Si vous êtes déconnecté, vous pouvez vous connecter à nouveau avec le nom d\'utilisateur {$recipientUsername}.</p><p>Si vous avez des questions, veuillez me contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Nous attendons de recevoir votre soumission révisée.</p><p>Cordialement,</p>{$signature}<hr><p>Remarques formulées dans les rapports d\'évaluation.</p>{$allReviewerComments}'),
(79,'EDITOR_DECISION_RESUBMIT','ar','إعادة التقديم للتحكيم','طلب تقديمك قد تمت مراجعته - يرجى تنقيحه وإعادة تسليمه','<p>عزيزي {$recipientName}،</p><p>بعد مراجعة طلب تقديمك، \"{$submissionTitle}\"، أوصى المحكمون بأنه لا يمكن قبوله للنشر بشكله الحالي. مع ذلك، نحن نحثك على تقديم نسخة منقحة تتناول ما زودنا به المحكمون من ملاحظات. تنقيحاتك سيتم النظر فيها من قبل أحد المحررين وقد يتم إرسالها في جولة تحكيم مناظر أخرى.</p><p>ترجى ملاحظة أن إعادة تقديم عملك لا تعني بالضرورة أنه سيتم قبوله.</p><p>ملاحظات المحكمين موجودة عند نهاية هذه الرسالة. يرجى الاستجابة لكل نقطة مذكورة في ملاحظات المحكمين وأعط وصفًا للتغيرات التي أجريتها. إذا وجدت أيًا من ملاحظات المحكمين غير مبررة أو غير مناسبة، يرجى توضيح وجهة نظرك. إذا كانت لديك أسئلة بشأن التوصيات المسجلة على مراجعة عملك، يرجى تضمينها في إجابتك.</p><p>عندما تكمل تنقيحاتك، بإمكانك رفع المستندات المعدلة مع إجابتك بشأن ملاحظات المحكمين من خلال <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>. إذا خرجت من الموقع، بإمكانك معاودة تسجيل الدخول باستعمال اسم المستخدم {$recipientUsername}.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>نحن نتطلع لتلقي طلب تقديمك المنقح.</p><p>أطيب التحايا،</p>{$signature}<hr><p>الملاحظات الآتية تم تلقيها من طرف المحكمين.</p>{$allReviewerComments}'),
(80,'EDITOR_DECISION_RESUBMIT','en','Resubmit for Review','Your submission has been reviewed - please revise and resubmit','<p>Dear {$recipientName},</p><p>After reviewing your submission, \"{$submissionTitle}\", the reviewers have recommended that your submission cannot be accepted for publication in its current form. However, we would like to encourage you to submit a revised version that addresses the reviewers\' comments. Your revisions will be reviewed by an editor and may be sent out for another round of peer review.</p><p>Please note that resubmitting your work does not guarantee that it will be accepted.</p><p>The reviewers\' comments are included at the bottom of this email. Please respond to each point and identify what changes you have made. If you find any of the reviewer\'s comments inappropriate, please explain your perspective. If you have questions about the recommendations in your review, please include these in your response.</p><p>When you have completed your revisions, you can upload revised documents along with your response to the reviewers\' comments <a href=\"{$authorSubmissionUrl}\">at your submission dashboard</a>. If you have been logged out, you can login again with the username {$recipientUsername}.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>We look forward to receiving your revised submission.</p><p>Kind regards,</p>{$signature}<hr><p>The following comments were received from reviewers.</p>{$allReviewerComments}'),
(81,'EDITOR_DECISION_RESUBMIT','fr','Soumettre à nouveau pour évaluation','Votre soumission a été évaluée, veuillez la réviser et la soumettre à nouveau','<p>{$recipientName},</p><p>Après examen de votre soumission, « {$submissionTitle} », les évaluateur·rice·s ont recommandé que votre soumission ne soit pas acceptée pour publication dans sa forme actuelle. Toutefois, nous vous encourageons à soumettre une version révisée qui réponde à leurs commentaires. Vos révisions pourront faire l\'objet d\'une nouvelle évaluation par les pairs.</p><p>Veuillez noter que le fait de soumettre à nouveau votre travail ne garantit pas qu\'il sera accepté.</p><p>Les commentaires des rapports d\'évaluation figurent à la fin de ce courriel. Veuillez répondre à chacun d\'entre eux et indiquer les éventuelles modifications que vous avez apportées. Si vous estimez que certains commentaires ne sont pas justifiés, veuillez expliquer votre point de vue. Si vous avez des questions concernant votre évaluation, veuillez les inclure dans votre réponse.</p><p>Lorsque vous avez terminé vos révisions, vous pouvez télécharger les documents révisés ainsi que votre réponse aux commentaires des évaluateurs <a href=\"{$authorSubmissionUrl}\">sur votre tableau de bord de soumission</a>. Si vous avez été déconnecté, vous pouvez vous connecter à nouveau avec le nom d\'utilisateur {$recipientUsername}.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>Nous attendons de recevoir votre soumission révisée.</p><p>Cordialement,</p>{$signature}<hr><p>Remarques formulées dans les rapports d\'évaluation.</p>'),
(82,'EDITOR_DECISION_DECLINE','ar','طلب التقديم مرفوض','طلب تقديمك قد تم رفضه','<p>عزيزي {$recipientName}،</p><p>بينما نحن نقدر تلقينا لطلب تقديمك، لا يمكننا قبول \"{$submissionTitle}\" للنشر على أساس ما تلقيناه من ملاحظات عنه من المحكمين.</p><p>ملاحظات المحكمين موجودة عند نهاية هذه الرسالة.</p><p>شكرًا على تقديم عملك إلى {$contextName}. على الرغم من أنه قد يكون مخيبًا للآمال رفض طلب التقديم، أرجو بأنك ستجد ملاحظات المحكمين بناءة ومفيدة.</p><p>أنت حر الآن في تقديم عملك إلى جهة أخرى إذا رغبت في ذلك.</p><p>أطيب التحايا،</p>{$signature}<hr><p>Tالملاحظات الآتية تم تلقيها من طرف المحكمين.</p>{$allReviewerComments}'),
(83,'EDITOR_DECISION_DECLINE','en','Submission Declined','Your submission has been declined','<p>Dear {$recipientName},</p><p>While we appreciate receiving your submission, we are unable to accept \"{$submissionTitle}\" for publication on the basis of the comments from reviewers.</p><p>The reviewers\' comments are included at the bottom of this email.</p><p>Thank you for submitting to {$contextName}. Although it is disappointing to have a submission declined, I hope you find the reviewers\' comments to be constructive and helpful.</p><p>You are now free to submit the work elsewhere if you choose to do so.</p><p>Kind regards,</p>{$signature}<hr><p>The following comments were received from reviewers.</p>{$allReviewerComments}'),
(84,'EDITOR_DECISION_DECLINE','fr','Soumission refusée','Votre soumission a été refusée','<p>{$recipientName},</p><p>Bien que nous vous soyons reconnaissants d\'avoir bien voulu nous faire parvenir votre soumission, nous ne sommes pas en mesure d\'accepter « {$submissionTitle} » pour publication sur la base des commentaires des évaluateur·rice·s, , que vous trouverez au bas de ce courriel.</p><p>Nous vous remercions d\'avoir envoyé votre soumission à {$contextName}. Bien qu\'il soit décevant de voir sa soumission refusée, j\'espère que vous trouverez les commentaires des évaluateur·rice·s constructifs et utiles.</p><p>Désormais, vous pouvez soumettre votre travail à une autre maison d\'édition si vous le souhaitez.</p><p>Cordialement,</p>{$signature}<hr><p>Remarques formulées dans les rapports d\'évaluation.</p>{$allReviewerComments}'),
(85,'EDITOR_DECISION_INITIAL_DECLINE','ar','طلب التقديم مرفوض (قبل التحكيم)','طلب تقديمك قد تم رفضه','<p>عزيزنا {$recipientName}،</p><p>يؤسفني إبلاغكم بأنه، وبعد مراجعة طلب تقديمكم، \"{$submissionTitle}\"، قد وجد المحرر بأنه لا يلبي متطلباتنا للنشر في {$contextName}.</p><p>أتمنى لكم النجاح إذا رغبتكم بتقديمه إلى جهة أخرى.</p><p>أطيب التحايا،</p>{$signature}'),
(86,'EDITOR_DECISION_INITIAL_DECLINE','en','Submission Declined (Pre-Review)','Your submission has been declined','<p>Dear {$recipientName},</p><p>I’m sorry to inform you that, after reviewing your submission, \"{$submissionTitle}\", the editor has found that it does not meet our requirements for publication in {$contextName}.</p><p>I wish you success if you consider submitting your work elsewhere.</p><p>Kind regards,</p>{$signature}'),
(87,'EDITOR_DECISION_INITIAL_DECLINE','fr','Soumission refusée avant évaluation','Votre soumission a été refusée','<p>{$recipientName},</p><p>J\'ai le regret de vous informer qu\'après avoir examiné votre soumission, « {$submissionTitle} », nous avons constaté qu\'elle ne répondait pas aux critères de publication de {$contextName}.</p><p>Je vous souhaite beaucoup de succès si vous envisagez de soumettre votre travail ailleurs.</p><p>Cordialement,</p>{$signature}'),
(88,'EDITOR_RECOMMENDATION','ar','التوصية معطاة','توصية المحرر','<p>عزيزي {$recipientName}،</p><p>بعد الأخذ بعين الاعتبار ما أفادنا به المحكمون، أود اتخاذ التوصية الآتية بشأن طلب التقديم \"{$submissionTitle}\".</p><p>توصيتي هي: {$recommendation}.</p><p>يرجى زيارة <a href=\"{$submissionUrl}\">سير أعمال التحرير</a> لطلب التقديم للتصرف وفقًا لتلك التوصية.</p><p>أرجو أن لا تتردد في التواصل معي إذا كانت لديك أية استفسارات.</p><p>أطيب التحايا،</p><p>{$senderName}</p>'),
(89,'EDITOR_RECOMMENDATION','en','Recommendation Made','Editor Recommendation','<p>Dear {$recipientName},</p><p>After considering the reviewers\' feedback, I would like to make the following recommendation regarding the submission \"{$submissionTitle}\".</p><p>My recommendation is: {$recommendation}.</p><p>Please visit the submission\'s <a href=\"{$submissionUrl}\">editorial workflow</a> to act on this recommendation.</p><p>Please feel free to contact me with any questions.</p><p>Kind regards,</p><p>{$senderName}</p>'),
(90,'EDITOR_RECOMMENDATION','fr','Recommandation émise','Recommandation éditoriale','<p>Cher {$recipientName}, </p><p>Après réception des évaluations par les pairs, nous souhaitons vous faire la recommandation suivante concernant la soumission « {$submissionTitle} » :</p><p>{$recommendation}.</p><p>Veuillez consulter la <a href=\"{$submissionUrl}\">page de la soumission</a> pour donner suite à cette recommandation.</p><p>N\'hésitez pas à me contacter si vous avez des questions.</p><p>Cordialement,</p><p>{$senderName}</p>'),
(91,'EDITOR_DECISION_NOTIFY_OTHER_AUTHORS','ar','إشعار المؤلفين الآخرين','مستجدات بشأن طلب تقديمك','<p>رسالة البريد الالكتروني الآتية أُرسلت إلى {$submittingAuthorName} من {$contextName} بشأن \"{$submissionTitle}\".</p>\n<p>أنت تتلقى نسخة من هذا الإشعار لأنك مُعرَّف كمؤلف لطلب التقديم. أي تعليمات في الرسالة أدناه هي موجهة إلى المؤلف المقدم للطلب، {$submittingAuthorName}، وليس هناك إجراء مطلوب منك القيام به في الوقت الراهن.</p>\n\n{$messageToSubmittingAuthor}'),
(92,'EDITOR_DECISION_NOTIFY_OTHER_AUTHORS','en','Notify Other Authors','An update regarding your submission','<p>The following email was sent to {$submittingAuthorName} from {$contextName} regarding \"{$submissionTitle}\".</p>\n<p>You are receiving a copy of this notification because you are identified as an author of the submission. Any instructions in the message below are intended for the submitting author, {$submittingAuthorName}, and no action is required of you at this time.</p>\n\n{$messageToSubmittingAuthor}'),
(93,'EDITOR_DECISION_NOTIFY_OTHER_AUTHORS','fr','Informer les autres auteur·e·s','Mise à jour concernant votre soumission','<p>Ce courriel a été envoyé à {$submittingAuthorName} par {$contextName} concernant « {$submissionTitle} ».</p>\n<p>Vous recevez une copie de cette notification parce que vous êtes identifié·e comme auteur·e de cette soumission. Les instructions contenues dans le message ci-dessous sont destinées au déposant, {$submittingAuthorName}, et aucune action n\'est requise de votre part à ce stade.</p>\n\n{$messageToSubmittingAuthor}'),
(94,'EDITOR_DECISION_NOTIFY_REVIEWERS','ar','إشعار المحكمين بالقرار','شكرًا على تحكيمك','<p>عزيزي {$recipientName}،</p>\n<p>شكرًا لإكمالك تحكيمك لطلب التقديم، \"{$submissionTitle}\"، لصالح {$contextName}. نحن نقدر وقتك وخبراتك التي ساهمت بهما لتعزيز جودة الأعمال التي ننشرها لقد شاركنا ملاحظاتك مع المؤلفين، مع ملاظات المحكمين الآخرين وقرار المحرر.</p>\n<p>بناءً على الإفادات التي تلقيناها، لقد أبلغنا المؤلفين بما مفاده:</p>\n<p>{$decisionDescription}</p>\n<p>لقد أخذنا بنظر الاعتبار توصياتك جنبًا إلى جنب مع توصيات المحكمين الآخرين قبل التوصل إلى القرار. أحيانًا قد يختلف قرار المحرر عن توصيات أحد المحكمين أو أكثر. يأخذ المحرر بعين الاعتبار عوامل عديدة، ولا يتخذ تلك القرارات بسهولة. نحن ممتنون لخبرات محكمينا ومقترحاتهم.</p>\n<p>لنا الشرف بالعمل معكم كمحكم في {$contextName}، ونأمل أن تتاح لنا فرصة العمل معكم مرة أخرى مستقبلاً.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>'),
(95,'EDITOR_DECISION_NOTIFY_REVIEWERS','en','Notify Reviewers of Decision','Thank you for your review','<p>Dear {$recipientName},</p>\n<p>Thank you for completing your review of the submission, \"{$submissionTitle}\", for {$contextName}. We appreciate your time and expertise in contributing to the quality of the work that we publish. We have shared your comments with the authors, along with our other reviewers\' comments and the editor\'s decision.</p>\n<p>Based on the feedback we received, we have notified the authors of the following:</p>\n<p>{$decisionDescription}</p>\n<p>Your recommendation was considered alongside the recommendations of other reviewers before coming to a decision. Occasionally the editor\'s decision may differ from the recommendation made by one or more reviewers. The editor considers many factors, and does not take these decisions lightly. We are grateful for our reviewers\' expertise and suggestions.</p>\n<p>It has been a pleasure to work with you as a reviewer for {$contextName}, and we hope to have the opportunity to work with you again in the future.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>'),
(96,'EDITOR_DECISION_NOTIFY_REVIEWERS','fr','Informer les évaluateur·rice·s de la décision','Merci pour votre évaluation','<p>{$recipientName},</p>\n<p>Nous vous remercions d\'avoir évalué la soumission « {$submissionTitle} » pour {$contextName}. Nous apprécions le temps et l\'expertise que vous avez consacrés à la qualité des travaux que nous publions. Nous avons transmis vos commentaires et ceux d\'autres évaluations aux auteur·e·s.</p>\n<p>Sur la base des commentaires que nous avons reçus, nous avons notifié aux auteur·e·s ce qui suit :</p>\n<p>{$decisionDescription}</p>\n<p>Votre recommandation a été examinée conjointement avec celles des autres évaluateur·rice·s avant d\'aboutir à cette décision.</p>\n<p>Cela a été un plaisir de travailler avec vous dans le cadre de cette évaluation pour {$contextName}. Nous espérons avoir l\'occasion de travailler à nouveau avec vous à l\'avenir.</p>\n<p>Cordialement,</p>\n<p>{$signature}</p>'),
(97,'EDITOR_DECISION_NEW_ROUND','ar','جولة تحكيم جديدة تم الشروع بها','طلب تقديمك قد تم إرساله إلى جولة تحكيم أخرى','<p>عزيزنا {$recipientName}،</p>\n<p>طلب تقديمكم المنقح، \"{$submissionTitle}\"، قد تم إرساله إلى جولة تحكيم مناظر جديدة. \nستتلقون منا رسائل فيها ملاحظات المحكمين ومعلومات عن الخطوات اللاحقة.</p>\n<p>إذا كانت لديكم أي أسئلة، يرجى التواصل معي <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>\n'),
(98,'EDITOR_DECISION_NEW_ROUND','en','New Review Round Initiated','Your submission has been sent for another round of review','<p>Dear {$recipientName},</p>\n<p>Your revised submission, \"{$submissionTitle}\", has been sent for a new round of peer review. \nYou will hear from us with feedback from the reviewers and information about the next steps.</p>\n<p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>\n'),
(99,'EDITOR_DECISION_NEW_ROUND','fr','Un nouveau cycle d\'évaluation a été lancé','Votre soumission fera l\'objet d\'un nouveau cycle d\'évaluation','<p>{$recipientName},</p>\n<p>Votre soumission évaluée, « {$submissionTitle} », fera l\'objet d\'un nouveau cycle d\'évaluation par les pairs. \nNous vous contacterons pour vous faire part des commentaires formulés dans les rapports d\'évaluation et vous fournir des informations sur les prochaines étapes.</p>\n<p>Si vous avec des questions, vous pouvez nous contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p>\n<p>Cordialement,</p>\n<p>{$signature}</p>\n'),
(100,'EDITOR_DECISION_REVERT_DECLINE','ar','إرجاع طلب تقديم مرفوض','لقد قمنا بإلغاء قرار رفض طلب تقديمكم','<p>عزيزنا {$recipientName}،</p>\n<p>قرار رفض طلب تقديمكم، \"{$submissionTitle}\"، قد تم التراجع عنه.\nسيقوم المحرر بإكمال جولة التحكيم وسيتم إبلاغكم عند اتخذ القرار.</p>\n<p>أحيانًا، يتم تسجيل قرار رفض طلب التقديم عرضيًا في نظامنا ولا بد من التراجع عنه. أقدم إعتذاري عن أي لبس قد يكون حدث بسبب ذلك.</p>\n<p>سنتواصل معكم إذا كنا بحاجة إلى أي مساعدة إضافية.</p>\n<p>إذا كانت لديكم أي أسئلة، يرجى التواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>\n'),
(101,'EDITOR_DECISION_REVERT_DECLINE','en','Reinstate Declined Submission','We have reversed the decision to decline your submission','<p>Dear {$recipientName},</p>\n<p>The decision to decline your submission, \"{$submissionTitle}\", has been reversed. \nAn editor will complete the round of review and you will be notified when a \ndecision is made.</p>\n<p>Occasionally, a decision to decline a submission will be recorded accidentally in \nour system and must be reverted. I apologize for any confusion this may have caused.</p>\n<p>We will contact you if we need any further assistance.</p>\n<p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>\n'),
(102,'EDITOR_DECISION_REVERT_DECLINE','fr','Rétablir une soumission refusée','Nous avons annulé la décision de rejeter votre envoi','<p>{$recipientName},</p>\n<p>La décision de ne pas accepter votre soumission, « {$submissionTitle} », a été annulée. À la fin du cycle d\'évaluation, vous serez informé de la décision prise. </p>\n<p>Il arrive qu\'une décision de refus soit accidentellement enregistrée dans notre système et doive être annulée. Nous vous prions de nous excuser pour la gêne occasionnée.</p>\n<p>Nous vous contacterons si nous avons besoin de votre aide.</p>\n<p>Si vous avez des questions, vous pouvez nous contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumissions</a>.</p>\n<p>Cordialement,</p>\n<p>{$signature}</p>\n'),
(103,'EDITOR_DECISION_REVERT_INITIAL_DECLINE','ar','إرجاع طلب تقديم مرفوض بدون تحكيم','لقد قمنا بالتراجع عن قرار رفض طلب تقديمكم','<p>عزيزنا {$recipientName}،</p>\n<p>قرار رفض طلب تقديمكم، \"{$submissionTitle}\"، قد تم التراجع عنه.\nسيقوم المحرر بفحص طلب تقديمكم بإمعان أكثر قبل أن يقرر ما إذا كان عليه رفضه أو إرساله إلى التحكيم.</p>\n<p>أحيانًا، يتم تسجيل قرار رفض طلب التقديم عرضيًا في نظامنا ولا بد من التراجع عنه. أقدم إعتذاري عن أي لبس قد يكون حدث بسبب ذلك.</p>\n<p>سنتواصل معكم إذا كنا بحاجة إلى أي مساعدة إضافية.</p>\n<p>إذا كانت لديكم أي أسئلة، يرجى التواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>\n'),
(104,'EDITOR_DECISION_REVERT_INITIAL_DECLINE','en','Reinstate Submission Declined Without Review','We have reversed the decision to decline your submission','<p>Dear {$recipientName},</p>\n<p>The decision to decline your submission, \"{$submissionTitle}\", has been reversed. \nAn editor will look further at your submission before deciding whether to decline \nthe submission or send it for review.</p>\n<p>Occasionally, a decision to decline a submission will be recorded accidentally in \nour system and must be reverted. I apologize for any confusion this may have caused.</p>\n<p>We will contact you if we need any further assistance.</p>\n<p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>\n'),
(105,'EDITOR_DECISION_REVERT_INITIAL_DECLINE','fr','Rétablir une soumission refusée sans évaluation','Nous avons annulé la décision de rejeter votre envoi','<p>{$recipientName},</p>\n<p>La décision de ne pas accepter votre soumission, « {$submissionTitle} », a été annulée.\nVotre soumission sera examinée plus en détail avant de décider de la refuser ou de l\'envoyer pour évaluation.</p>\n<p>Il arrive qu\'une décision de refus soit accidentellement enregistrée dans notre système et doive être annulée. Nous vous prions de nous excuser pour la gêne occasionnée.</p>\n<p>Nous vous contacterons si nous avons besoin de votre aide.</p>\n<p>Si vous avez des questions, vous pouvez nous contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumissions</a>.</p>\n<p>Bien cordialement,</p>\n<p>{$signature}</p>\n'),
(106,'EDITOR_DECISION_SKIP_REVIEW','ar','التحكيم متخطى','طلب تقديمك تمت إعادته إلى التدقيق','<p>عزيزي {$recipientName}،</p>\n<p>يسعدني إبلاغك بأننا قررنا قبول طلب تقديمك بدون إجراء التحكيم المناظر. لقد وجدنا بأن طلب تقديمك، {$submissionTitle}، يلبي توقعاتنا، ولا يتطلب عمل من هذا النوع أن يخضع لإجراءات التحكيم المناظر. نحن نتوقع نشر عملك في {$contextName} ونشكرك على اختيار مجلتنا محلاً لإظهار عملك.</p>\n<p>طلب تقديمك من المتوقع نشره في عدد قادم من {$contextName} ويسعدنا أن تضمنه في قائمة أعمالك المنشورة. نحن نميز الجهد المبذول وراء كل طلب تقديم ناجح ونود تهنئتك على هذا المجهود.</p>\n<p>سيخضع طلب تقديمك الآن إلى التدقيق الإملائي والتنسيق لتحضيره للنشر.</p>\n<p>ستتلقى قريبًا المزيد من التعليمات.</p>\n<p>إن كانت لديك أي أسئلة، يرجى التواصل معي من <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب تقديمك</a>.</p>\n<p>أطيب التحايا،</p>\n<p>{$signature}</p>\n'),
(107,'EDITOR_DECISION_SKIP_REVIEW','en','Submission Accepted (Without Review)','Your submission has been sent for copyediting','<p>Dear {$recipientName},</p>\n<p>I am pleased to inform you that we have decided to accept your submission without peer review. We found your submission, {$submissionTitle}, to meet our expectations, and we do not require that work of this type undergo peer review. We are excited to publish your piece in {$contextName} and we thank you for choosing our journal as a venue for your work.</p>\nYour submission is now forthcoming in a future issue of {$contextName} and you are welcome to include it in your list of publications. We recognize the hard work that goes into every successful submission and we want to congratulate you on your efforts.</p>\n<p>Your submission will now undergo copy editing and formatting to prepare it for publication. </p>\n<p>You will shortly receive further instructions.</p>\n<p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p>\n<p>Kind regards,</p>\n<p>{$signature}</p>\n'),
(108,'EDITOR_DECISION_SKIP_REVIEW','fr','Soumission acceptée (sans évaluation)','Votre soumission a été envoyée à la révision linguistique','<p>{$recipientName},</p>\n<p>Nous avons le plaisir de vous informer que nous avons décidé d\'accepter votre soumission sans processus d\'évaluation par les pairs. Nous trouvons que votre soumission, {$submissionTitle}, répond à nos exigences et ne requerrons pas une évaluation par les pairs. Nous sommes enthousiastes à l\'idée de publier votre texte dans la revue {$contextName} et voulons vous remercier d\'avoir choisi notre revue pour diffuser vos travaux. </p>\nVotre texte sera publié dans un prochain numéro de la revue {$contextName} et vous pouvez l\'inclure dès à présent dans votre liste de publications. Nous reconnaissons les efforts nécessaire à toute publication et vous en félicitons. </p>\n<p>Votre texte va faire l\'objet d\'une révision linguistique et être mise en page avant publication.</p>\n<p>Vous recevrez des instructions sous peu.</p>\n<p>Si vous avez des questions, n\'hésitez pas à me contacter à partir de votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p>\n<p>Cordialement,</p>\n<p>{$signature}</p>\n'),
(109,'EDITOR_DECISION_BACK_FROM_PRODUCTION','ar','طلب التقديم أُعيد إلى التدقيق','طلب تقديمك قد تمت إعادته إلى مرحلة التدقيق الإملائي','<p>عزيزي {$recipientName}،</p><p>طلب تقديمك، \"{$submissionTitle}\"، قد تمت إعادته إلى مرحلة التدقيق الإملائي، حيث سيخضك إلى مزيد من إجراءات التدقيق والتنسيق لتحضيره للنشر.</p><p>أحيانًا، يتم إرسال طلب التقديم إلى مرحلة الإنتاج قبل أن يكون جاهزًا من أجل تحضير الألواح الطباعية لمرحلة الإنتاج. طلب تقديمك لا يزال متوقعًا للنشر مستقبلاً. أقدم إعتذاري لأي لبس.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>سنتواصل معك إذا كنا بحاجة إلى أي مساعدة إضافية.</p><p>أطيب التحايا،</p><p>{$signature}</p>'),
(110,'EDITOR_DECISION_BACK_FROM_PRODUCTION','en','Submission Sent Back to Copyediting','Your submission has been sent back to copyediting','<p>Dear {$recipientName},</p><p>Your submission, \"{$submissionTitle}\", has been sent back to the copyediting stage, where it will undergo further copyediting and formatting to prepare it for publication.</p><p>Occasionally, a submission is sent to the production stage before it is ready for the final galleys to be prepared for publication. Your submission is still forthcoming. I apologize for any confusion.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>We will contact you if we need any further assistance.</p><p>Kind regards,</p><p>{$signature}</p>'),
(111,'EDITOR_DECISION_BACK_FROM_PRODUCTION','fr','Soumission renvoyée à l\'étape d\'édition','Votre soumission a été renvoyée pour édition','<p>{$recipientName},</p><p>Votre soumission, « {$submissionTitle} » a été renvoyée à l\'étape de révision, où elle fera l\'objet d\'une nouvelle révision et d\'une mise en forme en vue de sa publication.</p><p>Il arrive parfois qu\'une soumission soit envoyée à l\'étape de production avant qu\'elle ne soit prête pour les épreuves finales avant publication. Votre soumission est toujours en cours de traitement. Nous vous prions de nous excuser pour la confusion qui a pu en résulter.</p><p>Si vous avez des questions, vous pouvez nous contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Nous vous contacterons si nous avons besoin de votre aide.</p><p>Cordialement,</p><p>{$signature}</p>'),
(112,'EDITOR_DECISION_BACK_FROM_COPYEDITING','ar','طلب التقديم تم إرجاعه من التدقيق اللغوي','طلب تقديمك قد تمت إعادته إلى مرحلة التحكيم','<p>عزيزي {$recipientName}،</p><p>طلب تقديمك، \"{$submissionTitle}\"، قد تمت إعادته إلى مرحلة التحكيم. سيخضع إلى المزيد من إجراءات التحكيم قبل أن يكون مقبولاً للنشر.</p><p>أحيانًا، قد يحدث أن يجري تسجيل قبول العمل للنشر عرضًا في نظامنا وعلينا إعادته إلى التحكيم. أقدم إعتذاري لأي لبس قد يكون مترتبًا على ذلك. سنعمل على تسريع أعمال التحكيم لنتوصل إلى قرار نهائي بشأن قبول عملك في أقرب وقت ممكن.</p><p>سنتواصل معك إذا كنا بحاجة إلى أي مساعدة إضافية.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>أطيب التحايا،</p><p>{$signature}</p>'),
(113,'EDITOR_DECISION_BACK_FROM_COPYEDITING','en','Submission Sent Back from Copyediting','Your submission has been sent back to review','<p>Dear {$recipientName},</p><p>Your submission, \"{$submissionTitle}\", has been sent back to the review stage. It will undergo further review before it can be accepted for publication.</p><p>Occasionally, a decision to accept a submission will be recorded accidentally in our system and we must send it back to review. I apologize for any confusion this has caused. We will work to complete any further review quickly so that you have a final decision as soon as possible.</p><p>We will contact you if we need any further assistance.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>Kind regards,</p><p>{$signature}</p>'),
(114,'EDITOR_DECISION_BACK_FROM_COPYEDITING','fr','Soumission renvoyée de l\'étape d\'édition','Votre soumission a été renvoyée pour évaluation','<p>{$recipientName},</p><p>Votre soumission, « {$submissionTitle} », a été renvoyée à l\'étape d\'évaluation. Elle fera l\'objet d\'évaluations supplémentaires avant d\'être acceptée pour publication.</p><p>Il arrive parfois que la décision d\'accepter une soumission soit enregistrée accidentellement dans notre système et que nous devions la renvoyer pour qu\'elle soit évaluée. Nous vous prions de nous excuser pour la confusion que cela a pu occasionner. Nous veillerons à ce que tout nouvelle évaluation soit effectuée rapidement afin que vous puissiez disposer d\'une décision finale dans les meilleurs délais.</p><p>Nous vous contacterons si nous avons besoin de votre aide.</p><p>Si vous avez des questions, veuillez me contacter via votre <a href=\"{$authorSubmissionUrl}\">tableau de bord de soumission</a>.</p><p>Cordialement,</p><p>{$signature}</p>'),
(115,'EDITOR_DECISION_CANCEL_REVIEW_ROUND','ar','جولة التحكيم أُلغيت','جولة تحكيم لطلب تقديمك قد تم إلغاؤها','<p>عزيزي {$recipientName}،</p><p>لقد فتحنا مؤخرًا جولة تحكيم جديدة لطلب تقديمك، \"{$submissionTitle}\". نحن نغلق تلك الجولة الآن.</p><p>أحيانًا، قرار فتح جولة تحكيم جديدة قد يجري تسجيله في نظامنا عرضًا وعلينا إلغاء تلك الجولة. أقدم إعتذاري لأي لبس قد يكون مترتبًا جراء ذلك.</p><p>سنتواصل معك إذا كنا بحاجة إلى أي مساعدة إضافية.</p><p>إذا كانت لديك أي استفسارات، لطفًا تواصل معي عبر <a href=\"{$authorSubmissionUrl}\">دفة قيادة طلب التقديم</a>.</p><p>أطيب التحايا،</p><p>{$signature}</p>'),
(116,'EDITOR_DECISION_CANCEL_REVIEW_ROUND','en','Review Round Cancelled','A review round for your submission has been cancelled','<p>Dear {$recipientName},</p><p>We recently opened a new review round for your submission, \"{$submissionTitle}\". We are closing this review round now.</p><p>Occasionally, a decision to open a round of review will be recorded accidentally in our system and we must cancel this review round. I apologize for any confusion this may have caused.</p><p>We will contact you if we need any further assistance.</p><p>If you have any questions, please contact me from your <a href=\"{$authorSubmissionUrl}\">submission dashboard</a>.</p><p>Kind regards,</p><p>{$signature}</p>'),
(117,'EDITOR_DECISION_CANCEL_REVIEW_ROUND','fr','Cycle d\'évaluation annulé','Un cycle d\'évaluation de votre soumission a été annulé','<p>{$recipientName},</p><p>Nous avons récemment ouvert un nouveau cycle d\'évaluation pour votre soumission, « {$submissionTitle} », mais nous mettons fin à ce cycle.</p><p>Il arrive parfois que la décision d\'ouvrir un cycle d\'examen soit enregistrée accidentellement dans notre système et que nous devions l\'annuler. Nous vous prions de nous excuser pour toute confusion que cela a pu occasionner.</p><p>Nous vous contacterons si nous avons besoin de votre aide.</p><p>Si vous avez des questions, veuillez me contacter via votre <a href=\"{$authorSubmissionUrl}\"> tableau de bord de soumission.</a>.</p><p>Cordialement,</p><p>{$signature}</p>'),
(118,'SUBSCRIPTION_NOTIFY','ar','إشعار الاشتراك','إشعار الإشتراك','{$recipientName}:<br />\n<br />\nلقد حزت على الإشتراك في موقع مجلتنا على الإنترنت والتي تحمل اسم {$contextName}، وإن هذا الإشتراك هو من نوع:<br />\n<br />\n{$subscriptionType}<br />\n<br />\nللوصول إلى المحتوى المخصص للمشتركين حصراً، ببساطة قم بالدخول إلى الموقع مستعملاً اسم الدخول: &quot;{$recipientUsername}&quot;.<br />\n<br />\nبمجرد دخولك إلى النظام، يمكنك تعديل تفاصيل ملفك التعريفي وكلمة مرورك وفي أي وقت تشاء.<br />\n<br />\nلاحظ لطفاً أنك إن كنت حاصلاً على اشتراك مؤسساتي، فلا داعي لأفراد مؤسستك لتسجيل دخولهم إلى الموقع، طالماً أن محتوى طلبات الإشتراك ستكون عندها مصرحاً لها تلقائياً في النظام.<br />\n<br />\nإن كانت لديك أية استفسارات، فلا تتردد في مراسلتي.<br />\n<br />\n{$subscriptionSignature}'),
(119,'SUBSCRIPTION_NOTIFY','en','Subscription Notify','Subscription Notification','{$recipientName}:<br />\n<br />\nYou have now been registered as a subscriber in our online journal management system for {$contextName}, with the following subscription:<br />\n<br />\n{$subscriptionType}<br />\n<br />\nTo access content that is available only to subscribers, simply log in to the system with your username, &quot;{$recipientUsername}&quot;.<br />\n<br />\nOnce you have logged in to the system you can change your profile details and password at any point.<br />\n<br />\nPlease note that if you have an institutional subscription, there is no need for users at your institution to log in, since requests for subscription content will be automatically authenticated by the system.<br />\n<br />\nIf you have any questions, please feel free to contact me.<br />\n<br />\n{$subscriptionSignature}'),
(120,'SUBSCRIPTION_NOTIFY','fr','Notification d\'abonnement','Avis d\'abonnement','{$recipientName},<br />\n<br />\nVous êtes maintenant abonné à notre système de gestion en ligne pour {$contextName}, avec le type d\'abonnement suivant :<br />\n<br />\n{$subscriptionType}<br />\n<br />\nPour accéder au contenu destiné seulement aux abonnés, entrez dans le système à l\'aide de votre nom d\'utilisateur : {$recipientUsername}.<br />\n<br />\nUne fois dans le système, vous pouvez modifier les détails de votre profil et votre mot de passe en tout temps.<br />\n<br />\nVeuillez prendre note que si vous disposez d\'un abonnement institutionnel, les utilisateurs n\'ont pas à entrer de nom d\'utilisateur puisque le système authentifiera automatiquement les demandes.<br />\n<br />\nSi vous avez des questions, n\'hésitez pas à communiquer avec moi.<br />\n<br />\n{$subscriptionSignature}'),
(121,'OPEN_ACCESS_NOTIFY','ar','إشعار الوصول المفتوح','قراءة مجانية: صار الآن {$issueIdentification} من {$contextName} متاحًا بالمجان','<p>عزيزي {$recipientName}،</p><p>يسعدنا إبلاغكم بأن <a href=\"{$issueUrl}\">{$issueIdentification}</a> من {$contextName} صار متاحًا الآن بشكل مفتوح. لم يعد الاشتراك مطلوبًا لقراءة هذا العدد.</p><p>نشكر لكم إهتمامكم الدائم بنتاجاتنا.</p>{$contextSignature}'),
(122,'OPEN_ACCESS_NOTIFY','en','Open Access Notify','Free to read: {$issueIdentification} of {$contextName} is now open access','<p>Dear {$recipientName},</p><p>We are pleased to inform you that <a href=\"{$issueUrl}\">{$issueIdentification}</a> of {$contextName} is now available under open access.  A subscription is no longer required to read this issue.</p><p>Thank you for your continuing interest in our work.</p>{$contextSignature}'),
(123,'OPEN_ACCESS_NOTIFY','fr','Notification de diffusion en libre accès','Gratuitement accessible : le numéro {$issueIdentification} de la revue {$contextName} est maintenant en accès libre','<p>Chers lecteurs et lectrices,</p><p>{$contextName} vient de rendre disponible en libre accès le numéro <a href=\"{$issueUrl}\">{$issueIdentification}</a>. Nous vous invitons à visiter notre site Web ({$contextUrl}) pour lire les articles qui pourraient vous intéresser.</p><p>Nous vous remercions de l\'intérêt que vous portez à notre travail,</p>{$contextSignature}'),
(124,'SUBSCRIPTION_BEFORE_EXPIRY','ar','الاشتراك يوشك على الانتهاء','إشعار بانتهاء صلاحية الإشتراك','{$recipientName}:<br />\n<br />\nإن إشتراكك في {$contextName} على وشك الإنتهاء.<br />\n<br />\n{$subscriptionType}<br />\nتاريخ إنتهاء صلاحيته: {$expiryDate}<br />\n<br />\nلضمان استمرارية وصولك إلى هذه المجلة، لطفاً أدخل موقعها وجدد إشتراكك. بإمكانك الولوج إلى النظام مستعملاً اسم الدخول: &quot;{$recipientUsername}&quot;.<br />\n<br />\nإن كانت لديك أية استفسارات، فلا تتردد في مراسلتي.<br />\n<br />\n{$subscriptionSignature}'),
(125,'SUBSCRIPTION_BEFORE_EXPIRY','en','Subscription Expires Soon','Notice of Subscription Expiry','{$recipientName}:<br />\n<br />\nYour {$contextName} subscription is about to expire.<br />\n<br />\n{$subscriptionType}<br />\nExpiry date: {$expiryDate}<br />\n<br />\nTo ensure the continuity of your access to this journal, please go to the journal website and renew your subscription. You are able to log in to the system with your username, &quot;{$recipientUsername}&quot;.<br />\n<br />\nIf you have any questions, please feel free to contact me.<br />\n<br />\n{$subscriptionSignature}'),
(126,'SUBSCRIPTION_BEFORE_EXPIRY','fr','L\'abonnement arrive bientôt à échéance','Rappel de l\'expiration de l\'abonnement','{$recipientName},<br />\n<br />\nVotre abonnement à {$contextName} expirera bientôt.<br />\n<br />\n{$subscriptionType}<br />\nDate d\'expiration : {$expiryDate}<br />\n<br />\nAfin d\'assurer la continuité de votre accès à cette revue, nous vous prions d\'aller sur le site Web de la revue et de renouveler votre abonnement. Vous pouvez vous y ouvrir une session avec votre nom d\'utilisateur, &quot;{$recipientUsername}&quot;.<br />\n<br />\nSi vous avez des questions, ne pas hésiter à communiquer avec moi.<br />\n<br />\n{$subscriptionSignature}'),
(127,'SUBSCRIPTION_AFTER_EXPIRY','ar','الاشتراك منتهي','إنتهت صلاحية الإشتراك','{$recipientName}:<br />\n<br />\nإن مدة إشتراكك في {$contextName} قد انتهت.<br />\n<br />\n{$subscriptionType}<br />\nتاريخ إنتهاء صلاحيته: {$expiryDate}<br />\n<br />\nلتجديد إشتراكك، لطفاً أدخل موقع المجلة. بإمكانك الولوج إلى النظام مستعملاً اسم الدخول: &quot;{$recipientUsername}&quot;.<br />\n<br />\nإن كانت لديك أية استفسارات، فلا تتردد في مراسلتي.<br />\n<br />\n{$subscriptionSignature}'),
(128,'SUBSCRIPTION_AFTER_EXPIRY','en','Subscription Expired','Subscription Expired','{$recipientName}:<br />\n<br />\nYour {$contextName} subscription has expired.<br />\n<br />\n{$subscriptionType}<br />\nExpiry date: {$expiryDate}<br />\n<br />\nTo renew your subscription, please go to the journal website. You are able to log in to the system with your username, &quot;{$recipientUsername}&quot;.<br />\n<br />\nIf you have any questions, please feel free to contact me.<br />\n<br />\n{$subscriptionSignature}'),
(129,'SUBSCRIPTION_AFTER_EXPIRY','fr','Abonnement expiré','Abonnement expiré','{$recipientName},<br />\n<br />\nVotre abonnement à la revue {$contextName} est expiré.<br />\n<br />\n{$subscriptionType}<br />\nDate d\'expiration : {$expiryDate}<br />\n<br />\nPour renouveler votre abonnement, veuillez aller sur le site Web de la revue. Vous pouvez y ouvrir une session en utilisant votre nom d\'utilisateur, &quot;{$recipientUsername}&quot;.<br />\n<br />\nSi vous avez des questions, n\'hésitez pas à communiquer avec moi.<br />\n<br />\n{$subscriptionSignature}'),
(130,'SUBSCRIPTION_AFTER_EXPIRY_LAST','ar','الاشتراك المنتهي مؤخرًا','إنتهت صلاحية الإشتراك - التذكير الأخير','{$recipientName}:<br />\n<br />\nإن مدة إشتراكك في {$contextName} قد انتهت.<br />\nلطفاً، نشيرك إلى أن هذه الرسالة هي بمثابة التذكير الأخير بشأنه.<br />\n<br />\n{$subscriptionType}<br />\nتاريخ إنتهاء صلاحيته: {$expiryDate}<br />\n<br />\nلتجديد إشتراكك، لطفاً أدخل موقع المجلة. بإمكانك الولوج إلى النظام مستعملاً اسم الدخول: &quot;{$recipientUsername}&quot;.<br />\n<br />\nإن كانت لديك أية استفسارات، فلا تتردد في مراسلتي.<br />\n<br />\n{$subscriptionSignature}'),
(131,'SUBSCRIPTION_AFTER_EXPIRY_LAST','en','Subscription Expired Last','Subscription Expired - Final Reminder','{$recipientName}:<br />\n<br />\nYour {$contextName} subscription has expired.<br />\nPlease note that this is the final reminder that will be emailed to you.<br />\n<br />\n{$subscriptionType}<br />\nExpiry date: {$expiryDate}<br />\n<br />\nTo renew your subscription, please go to the journal website. You are able to log in to the system with your username, &quot;{$recipientUsername}&quot;.<br />\n<br />\nIf you have any questions, please feel free to contact me.<br />\n<br />\n{$subscriptionSignature}'),
(132,'SUBSCRIPTION_AFTER_EXPIRY_LAST','fr','Abonnement échu en dernier','Abonnement expiré - Dernier rappel','{$recipientName},<br />\n<br />\nVotre abonnement à la revue {$contextName} est expiré.<br/>\nVeuillez prendre note que ceci est le dernier rappel qui vous sera envoyé.<br />\n<br />\n{$subscriptionType}<br />\nDate d\'expiration : {$expiryDate}<br />\n<br />\nPour renouveller votre abonnement, aveuillez vous rendre sur le site Web de la revue. Vous pouvez y ouvrir une session avec votre nom d\'utilisateur ou d\'utilisatrice, soit &quot;{$recipientUsername}&quot;.<br />\n<br />\nSi vous avez des questions, n\'hésitez pas à communiquer avec nous.<br />\n<br />\n{$subscriptionSignature}'),
(133,'SUBSCRIPTION_PURCHASE_INDL','ar','شراء الاشتراك الفردي','شراء إشتراك: منفرد','لقد تم شراء إشتراك منفرد في المجلة {$contextName} عبر الإنترنت وبالتفاصيل أدناه:<br />\n<br />\nنوع الإشنراك:<br />\n{$subscriptionType}<br />\n<br />\nالمستخدم:<br />\n{$subscriberDetails}<br />\n<br />\nمعلومات العضوية (إن وجدت):<br />\n{$membership}<br />\n<br />\nلعرض أو تعديل هذا الاشتراك، لطفاً استعمل الرابط الآتي:<br />\n<br />\nرابط الاشتراك: {$subscriptionUrl}<br />\n'),
(134,'SUBSCRIPTION_PURCHASE_INDL','en','Purchase Individual Subscription','Subscription Purchase: Individual','An individual subscription has been purchased online for {$contextName} with the following details.<br />\n<br />\nSubscription Type:<br />\n{$subscriptionType}<br />\n<br />\nUser:<br />\n{$subscriberDetails}<br />\n<br />\nMembership Information (if provided):<br />\n{$membership}<br />\n<br />\nTo view or edit this subscription, please use the following URL.<br />\n<br />\nSubscription URL: {$subscriptionUrl}<br />\n'),
(135,'SUBSCRIPTION_PURCHASE_INDL','fr','Acheter un abonnement individuel','Souscription à un abonnement individuel','Une souscription en ligne à un abonnement individuel pour la revue {$contextName} avec les renseignements suivants :<br />\n<br />\nType d\'abonnement :<br />\n{$subscriptionType}<br />\n<br />\nUtilisateur-trice :<br />\n{$subscriberDetails}<br />\n<br />\nInformation d\'adhésion (si fournie) :<br />\n{$membership}<br />\n<br />\nPour afficher ou modifier cet abonnement, veuillez utiliser l\'URL suivante.<br />\n<br />\nURL d\'abonnement : {$subscriptionUrl}<br/>\n'),
(136,'SUBSCRIPTION_PURCHASE_INSTL','ar','شراء الاشتراك المؤسساتي','شراء إشتراك: مؤسساتي','لقد تم شراء إشتراك مؤسساتي في المجلة {$contextName} عبر الإنترنت وبالتفاصيل أدناه، ولتفعيل هذا الإشتراك، لطفاً استعمل رابط الاشتراك وحول حالته إلى فعّال.<br />\n<br />\nنوع الإشنراك:<br />\n{$subscriptionType}<br />\n<br />\nالمؤسسة:<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nالمدى (إن توفر):<br />\n{$domain}<br />\n<br />\nمدى عناوين IP (إن توفرت):<br />\n{$ipRanges}<br />\n<br />\nالشخص المعني:<br />\n{$subscriberDetails}<br />\n<br />\nمعلومات العضوية (إن وجدت):<br />\n{$membership}<br />\n<br />\nلعرض أو تعديل هذا الاشتراك، لطفاً استعمل الرابط الآتي:<br />\n<br />\nرابط الاشتراك: {$subscriptionUrl}<br />\n'),
(137,'SUBSCRIPTION_PURCHASE_INSTL','en','Purchase Institutional Subscription','Subscription Purchase: Institutional','An institutional subscription has been purchased online for {$contextName} with the following details. To activate this subscription, please use the provided Subscription URL and set the subscription status to \'Active\'.<br />\n<br />\nSubscription Type:<br />\n{$subscriptionType}<br />\n<br />\nInstitution:<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nDomain (if provided):<br />\n{$domain}<br />\n<br />\nIP Ranges (if provided):<br />\n{$ipRanges}<br />\n<br />\nContact Person:<br />\n{$subscriberDetails}<br />\n<br />\nMembership Information (if provided):<br />\n{$membership}<br />\n<br />\nTo view or edit this subscription, please use the following URL.<br />\n<br />\nSubscription URL: {$subscriptionUrl}<br />\n'),
(138,'SUBSCRIPTION_PURCHASE_INSTL','fr','Acheter un abonnement institutionnel','Souscription à un abonnement institutionnel','Souscription en ligne à un abonnement institutionnel pour la revue {$contextName} avec les renseignements suivants. Pour activer cet abonnement, veuillez utiliser l\'URL d\'abonnement fourni et passer le statut de l\'abonnement à « actif ».<br />\n<br />\nType d\'abonnement :<br />\n{$subscriptionType}<br />\n<br />\nÉtablissement :<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nDomaine (si fourni) :<br />\n{$domain}<br />\n<br />\nPlage d\'adresses IP (si fournie) :<br />\n{$ipRanges}<br />\n<br />\nPersonne-ressource :<br />\n{$subscriberDetails}<br />\n<br />\nRenseignements d\'adhésion (si fournis) :<br />\n{$membership}<br />\n<br />\nPour afficher ou modifier cet abonnement, veuillez utiliser l\'URL suivant :<br />\n<br />\nURL de l\'abonnement : {$subscriptionUrl}<br />\n'),
(139,'SUBSCRIPTION_RENEW_INDL','ar','تجديد الاشتراك الفردي','تجديد إشتراك: منفرد','لقد تم تجديد إشتراك منفرد في المجلة {$contextName} عبر الإنترنت وبالتفاصيل أدناه:<br />\n<br />\nنوع الإشنراك:<br />\n{$subscriptionType}<br />\n<br />\nالمستخدم:<br />\n{$subscriberDetails}<br />\n<br />\nمعلومات العضوية (إن وجدت):<br />\n{$membership}<br />\n<br />\nلعرض أو تعديل هذا الاشتراك، لطفاً استعمل الرابط الآتي:<br />\n<br />\nرابط الاشتراك: {$subscriptionUrl}<br />\n'),
(140,'SUBSCRIPTION_RENEW_INDL','en','Renew Individual Subscription','Subscription Renewal: Individual','An individual subscription has been renewed online for {$contextName} with the following details.<br />\n<br />\nSubscription Type:<br />\n{$subscriptionType}<br />\n<br />\nUser:<br />\n{$subscriberDetails}<br />\n<br />\nMembership Information (if provided):<br />\n{$membership}<br />\n<br />\nTo view or edit this subscription, please use the following URL.<br />\n<br />\nSubscription URL: {$subscriptionUrl}<br />\n'),
(141,'SUBSCRIPTION_RENEW_INDL','fr','Renouveler l\'abonnement individuel','Renouvellement d\'abonnement : Individuel','Un abonnement individuel a été renouvelé en ligne pour la revue {$contextName} avec les renseignements suivants.<br />\n<br />\nType d\'abonnement :<br />\n{$subscriptionType}<br />\n<br />\nUtilisateur-trice :<br />\n{$subscriberDetails}<br />\n<br />\nRenseignements d\'adhésion (si fournis) :<br />\n{$membership}<br />\n<br />\nPour afficher ou modifier cet abonnement, veuillez utiliser l\'URL suivant.<br />\n<br />\nURL de l\'abonnement : {$subscriptionUrl}<br />\n'),
(142,'SUBSCRIPTION_RENEW_INSTL','ar','تجديد الاشتراك المؤسساتي','تجديد إشتراك: مؤسساتي','لقد تم تجديد إشتراك مؤسساتي في المجلة {$contextName} عبر الإنترنت وبالتفاصيل أدناه:<br />\n<br />\nنوع الإشنراك:<br />\n{$subscriptionType}<br />\n<br />\nالمؤسسة:<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nالمدى (إن توفر):<br />\n{$domain}<br />\n<br />\nمدى عناوين IP (إن توفرت):<br />\n{$ipRanges}<br />\n<br />\nالشخص المعني:<br />\n{$subscriberDetails}<br />\n<br />\nمعلومات العضوية (إن وجدت):<br />\n{$membership}<br />\n<br />\nلعرض أو تعديل هذا الاشتراك، لطفاً استعمل الرابط الآتي:<br />\n<br />\nرابط الاشتراك: {$subscriptionUrl}<br />\n'),
(143,'SUBSCRIPTION_RENEW_INSTL','en','Renew Institutional Subscription','Subscription Renewal: Institutional','An institutional subscription has been renewed online for {$contextName} with the following details.<br />\n<br />\nSubscription Type:<br />\n{$subscriptionType}<br />\n<br />\nInstitution:<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nDomain (if provided):<br />\n{$domain}<br />\n<br />\nIP Ranges (if provided):<br />\n{$ipRanges}<br />\n<br />\nContact Person:<br />\n{$subscriberDetails}<br />\n<br />\nMembership Information (if provided):<br />\n{$membership}<br />\n<br />\nTo view or edit this subscription, please use the following URL.<br />\n<br />\nSubscription URL: {$subscriptionUrl}<br />\n'),
(144,'SUBSCRIPTION_RENEW_INSTL','fr','Renouveler l\'abonnement institutionnel','Renouvellement d\'abonnement : Institutionnel','Un abonnement institutionnel a été renouvelé en ligne pour la revue {$contextName} avec les renseignements suivants.<br />\n<br />\nType d\'abonnement :<br />\n{$subscriptionType}<br />\n<br />\nÉtablissement :<br />\n{$institutionName}<br />\n{$institutionMailingAddress}<br />\n<br />\nDomaine (si fourni) :<br />\n{$domain}<br />\n<br />\nPlage d\'adresses IP (si fournie) :<br />\n{$ipRanges}<br />\n<br />\nPersonne-ressource :<br />\n{$subscriberDetails}<br />\n<br />\nRenseignements d\'adhésion (si fournis) :<br />\n{$membership}<br />\n<br />\nPour afficher ou modifier cet abonnement, veuillez utiliser l\'URL suivant.<br />\n<br />\nURL de l\'abonnement : {$subscriptionUrl}<br />\n'),
(145,'REVISED_VERSION_NOTIFY','ar','إشعار النسخة المنقحة','تم رفع نسخة منقحة','<p>عزيزي {$recipientName}،</p><p>قام المؤلف برفع نسخة منقحة من طلب التقديم،<b>{$authorsShort} — {$submissionTitle}</b>. <p>بصفتك المحرر المعين له، نلتمس منك تسجيل الدخول و <a href=\"{$submissionUrl}\">معاينة التنقيحات</a> واتخاذ القرار بقبولها، رفضها، أو إرسال طلب التقديم إلى جولة تحكيم أخرى.</p><br><br>—<br>هذه رسالة مؤتمتة من قبل <a href=\"{$contextUrl}\">{$contextName}</a>.'),
(146,'REVISED_VERSION_NOTIFY','en','Revised Version Notification','Revised Version Uploaded','<p>Dear {$recipientName},</p><p>The author has uploaded revisions for the submission, <b>{$authorsShort} — {$submissionTitle}</b>. <p>As an assigned editor, we ask that you login and <a href=\"{$submissionUrl}\">view the revisions</a> and make a decision to accept, decline or send the submission for further review.</p><br><br>—<br>This is an automated message from <a href=\"{$contextUrl}\">{$contextName}</a>.'),
(147,'REVISED_VERSION_NOTIFY','fr','Notification de version révisée','Version révisée téléversée','<p>Cher ou chère {$recipientName},</p><p>L\'auteur/ice a fourni une version révisée de sa soumission, <b>{$authorsShort} — {$submissionTitle}</b>.</p><p>En tant qu\'éditeur/ice assigné/e, nous vous demandons de vous connecter et de <a href=\"{$submissionUrl}\">consulter les révisions</a> et de prendre une décision pour accepter, refuser ou lancer un nouveau tour d\'évaluation.</p><br><br>—<br>Ceci est un message automatique de <a href=\"{$contextUrl}\">{$contextName}</a>.'),
(148,'STATISTICS_REPORT_NOTIFICATION','ar','إشعار التقرير الإحصائي','نشاط هيئة التحرير لشهر {$month}، {$year}','\n{$recipientName}, <br />\n<br />\nتقرير حالة مجلتك لشهر {$month}، {$year} متوافر حالياً. الأمور المفصلية لهذا الشهر هي كما يأتي.<br />\n<ul>\n	<li>عدد طلبات التقديم الجديدة: {$newSubmissions}</li>\n	<li>طلبات التقديم المرفوضة: {$declinedSubmissions}</li>\n	<li>طلبات التقديم المقبولة: {$acceptedSubmissions}</li>\n	<li>إجمالي طلبات التقديم في النظام: {$totalSubmissions}</li>\n</ul>\nسجل دخولك إلى المجلة لمعاينة <a href=\"{$editorialStatsLink}\">ما يشغل هيئة التحرير</a> بشكل مفصل فضلاً عن <a href=\"{$publicationStatsLink}\">حالة المقالات المنشورة</a>. لديك نسخة مرفقة بهذه الرسالة تتضمن كل مشاغل هيئة التحرير لهذا الشهر.<br />\n<br />\nمع التقدير<br />\n{$contextSignature}'),
(149,'STATISTICS_REPORT_NOTIFICATION','en','Statistics Report Notification','Editorial activity for {$month}, {$year}','\n{$recipientName}, <br />\n<br />\nYour journal health report for {$month}, {$year} is now available. Your key stats for this month are below.<br />\n<ul>\n	<li>New submissions this month: {$newSubmissions}</li>\n	<li>Declined submissions this month: {$declinedSubmissions}</li>\n	<li>Accepted submissions this month: {$acceptedSubmissions}</li>\n	<li>Total submissions in the system: {$totalSubmissions}</li>\n</ul>\nLogin to the journal to view more detailed <a href=\"{$editorialStatsLink}\">editorial trends</a> and <a href=\"{$publicationStatsLink}\">published article stats</a>. A full copy of this month\'s editorial trends is attached.<br />\n<br />\nSincerely,<br />\n{$contextSignature}'),
(150,'STATISTICS_REPORT_NOTIFICATION','fr','Notification de rapport statistique','Activité éditoriale pour {$month} {$year}','\n{$recipientName}, <br />\n<br />\nLe rapport d\'activité éditoriale de votre revue pour {$month} {$year} est maintenant disponible. Les principales statistiques pour ce mois sont affichées ci-dessous.<br />\n<ul>\n	<li> Nouvelles soumissions pour ce mois : {$newSubmissions} </li>\n	<li> Soumissions refusées pour ce mois : {$declinedSubmissions} </li>\n	<li> Soumissions acceptées pour ce mois : {$acceptedSubmissions} </li>\n	<li> Nombre total de soumissions dans la plateforme : {$totalSubmissions} </li>\n</ul>\nConnectez-vous au site de la revue pour voir davantage de <a href=\"{$editorialStatsLink}\">tendances dans l\'activité éditoriale</a> ainsi que des <a href=\"{$publicationStatsLink}\">statistiques relatives aux articles publiés</a>. Le rapport complet des tendances de l\'activité éditoriale de ce mois-ci est joint au présent envoi.<br />\n<br />\nCordialement,<br />\n{$contextSignature}'),
(151,'ANNOUNCEMENT','ar','إعلان جديد','{$announcementTitle}','<b>{$announcementTitle}</b><br />\n<br />\n{$announcementSummary}<br />\n<br />\nقم بزيارة موقعنا للاطلاع على <a href=\"{$announcementUrl}\">الإعلان بشكله الكامل</a>.'),
(152,'ANNOUNCEMENT','en','New Announcement','{$announcementTitle}','<b>{$announcementTitle}</b><br />\n<br />\n{$announcementSummary}<br />\n<br />\nVisit our website to read the <a href=\"{$announcementUrl}\">full announcement</a>.'),
(153,'ANNOUNCEMENT','fr','Nouvelle annonce','{$announcementTitle}','<b>{$announcementTitle}</b><br />\n<br />\n{$announcementSummary}<br />\n<br />\nVisiter notre site pour consulter <a href=\"{$announcementUrl}\">l\'annonce complète</a>.'),
(154,'DISCUSSION_NOTIFICATION_SUBMISSION','ar','تقديم المناقشة','رسالة تتعلق بـ {$contextName}','لطفاً أكتب رسالتك.'),
(155,'DISCUSSION_NOTIFICATION_SUBMISSION','en','Discussion (Submission)','A message regarding {$contextName}','Please enter your message.'),
(156,'DISCUSSION_NOTIFICATION_SUBMISSION','fr','Discussion (soumission)','Un message à propos de {$contextName}','Veuillez saisir votre message.'),
(157,'DISCUSSION_NOTIFICATION_REVIEW','ar','مناقشة التحكيم','رسالة تتعلق بـ {$contextName}','لطفاً أكتب رسالتك.'),
(158,'DISCUSSION_NOTIFICATION_REVIEW','en','Discussion (Review)','A message regarding {$contextName}','Please enter your message.'),
(159,'DISCUSSION_NOTIFICATION_REVIEW','fr','Discussion (évaluation)','Un message à propos de {$contextName}','Veuillez saisir votre message.'),
(160,'DISCUSSION_NOTIFICATION_COPYEDITING','ar','مناقشة التدقيق اللغوي','رسالة تتعلق بـ {$contextName}','لطفاً أكتب رسالتك.'),
(161,'DISCUSSION_NOTIFICATION_COPYEDITING','en','Discussion (Copyediting)','A message regarding {$contextName}','Please enter your message.'),
(162,'DISCUSSION_NOTIFICATION_COPYEDITING','fr','Discussion (édition)','Un message à propos de {$contextName}','Veuillez saisir votre message.'),
(163,'DISCUSSION_NOTIFICATION_PRODUCTION','ar','مناقشة الإنتاج','رسالة تتعلق بـ {$contextName}','لطفاً أكتب رسالتك.'),
(164,'DISCUSSION_NOTIFICATION_PRODUCTION','en','Discussion (Production)','A message regarding {$contextName}','Please enter your message.'),
(165,'DISCUSSION_NOTIFICATION_PRODUCTION','fr','Discussion (production)','Un message à propos de {$contextName}','Veuillez saisir votre message.'),
(166,'COPYEDIT_REQUEST','ar','إلتماس التدقيق اللغوي','طلب التقديم {$submissionId} جاهز لتدقيقه لصالح {$contextAcronym}','<p>عزيزي {$recipientName}،</p><p>طلب تقديم جديد جاهز لتدقيقه إملائيًا:</p><p><a href\"{$submissionUrl}\">{$submissionId} — \"{$submissionTitle}\"</a><br />{$contextName}</p><p>يرجى اتباع الخطوات الآتية لإكمال هذه المهمة:</p><ol><li>أنقر على رابط طلب النشر أدناه.</li><li>إفتح أي ملفات متوافرة ضمن الملفات المسودة وقم بتحريرها. استعمل منطقة مناقشات التدقيق إذا كنت بحاجة إلى مراسلة المحررين أو المؤلفين.</li><li>إحفظ الملفات المدققة، ثم إرفعها إلى لوحة المدققات.</li><li>استعمل منطقة مناقشات التدقيق لإشعار المحررين بأن كل الملفات صارت جاهزة وبأن عملية الإنتاج يمكنها أن تبدأ.</li></ol><p>إذا لم تكن قادرًا على تولي هذا العمل في الوقت الحالي أو لديك أي استفسارت، يرجى التواصل معي. شكرًا لمساهمتك مع {$contextName}.</p><p>أطيب التحايا،</p>{$signature}'),
(167,'COPYEDIT_REQUEST','en','Request Copyedit','Submission {$submissionId} is ready to be copyedited for {$contextAcronym}','<p>Dear {$recipientName},</p><p>A new submission is ready to be copyedited:</p><p><a href\"{$submissionUrl}\">{$submissionId} — \"{$submissionTitle}\"</a><br />{$contextName}</p><p>Please follow these steps to complete this task:</p><ol><li>Click on the Submission URL below.</li><li>Open any files available under Draft Files and edit the files. Use the Copyediting Discussions area if you need to contact the editor(s) or author(s).</li><li>Save the copyedited file(s) and upload them to the Copyedited panel.</li><li>Use the Copyediting Discussions to notify the editor(s) that all files have been prepared, and that the Production process may begin.</li></ol><p>If you are unable to undertake this work at this time or have any questions, please contact me. Thank you for your contribution to {$contextName}.</p><p>Kind regards,</p>{$signature}'),
(168,'COPYEDIT_REQUEST','fr','Demande d\'édition','La soumission {$submissionId} est prête à être éditée pour {$contextAcronym}','<p>{$recipientName},</p><p>Une nouvelle soumission est prête pour traitement éditorial :</p><p><a href\"{$submissionUrl}\">{$submissionId} — « {$submissionTitle} »</a><br />{$contextName}</p><p>Pouvez-vous suivre les étapes ci-dessous pour faire ce travail ?</p><ol><li>1. Cliquer sur l\'URL de la soumission ci-dessus.</li><li>2. Ouvrir le(s) fichier(s) disponible(s) sous Fichiers des ébauches finales et effectuer votre révision, tout en ajoutant des discussions sur la révision, le cas échéant.</li><li>3. Enregistrer le(s) fichier(s) révisé(s) et le(s) téléverser dans la section Version(s) révisée(s).</li><li>4. Informer l\'éditeur que tous les fichiers ont été révisés et que l\'étape de production peut débuter.</li></ol><p>Si vous n\'êtes pas en mesure d\'entreprendre ce travail pour le moment ou si vous avez des questions, n\'hésitez pas à nous contacter. Merci pour votre contribution à {$contextName}.</p><p>Cordialement,</p>{$signature}'),
(169,'EDITOR_ASSIGN_SUBMISSION','ar','تعيين المحرر','لقد تم تعيينك كمحرر لطلب التقديم الموجه إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>طلب التقديم الآتي قد تمت إحالته إليك لتقوم بإجراءات التحرير المتعلقة به.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>الملخص</b></p>{$submissionAbstract}<p>إذا وجدت بأن طلب التقديم ذي صلة بـ {$contextName}، يرجى تمريره إلى مرحلة التحكيم عبر اختيار \"الإرسال إلى التحكيم\" ومن ثم قم بتعيين المحكمين عبر النقر على \"إضافة محكم\".</p><p>إذا كان طلب التقديم غير مناسب لهذه المجلة، يرجى رفض الطلب.</p><p>شكرًا لك مقدمًا.</p><p>أطيب التحايا،</p>{$contextSignature}'),
(170,'EDITOR_ASSIGN_SUBMISSION','en','Assign Editor','You have been assigned as an editor on a submission to {$contextName}','<p>Dear {$recipientName},</p><p>The following submission has been assigned to you to see through the editorial process.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Abstract</b></p>{$submissionAbstract}<p>If you find the submission to be relevant for {$contextName}, please forward the submission to the review stage by selecting \"Send to Review\" and then assign reviewers by clicking \"Add Reviewer\".</p><p>If the submission is not appropriate for this journal, please decline the submission.</p><p>Thank you in advance.</p><p>Kind regards,</p>{$contextSignature}'),
(171,'EDITOR_ASSIGN_SUBMISSION','fr','Assigner un·e éditeur·rice','Vous avez été assigné.e en tant que rédacteur.trice d\'une soumission de la revue {$contextName}','<p>{$recipientName},</p><p>La soumission suivante vous a été assignée pour le suivi du processus éditorial.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Résumé</b></p>{$submissionAbstract}<p>Si vous jugez la soumission pertinente pour la revue {$contextName}, veuillez la transmettre à l\'étape d\'évaluation en sélectionnant « Envoyer en évaluation» et en désignant des évaluateur.trice.s en cliquant sur « Ajouter un.e évaluateur.trice ».</p><p>Si la soumission n\'est pas appropriée pour cette revue, veuillez la décliner.</p><p>Je vous remercie d\'avance.</p><p>Cordialement,</p>{$contextSignature}'),
(172,'EDITOR_ASSIGN_REVIEW','ar','تعيين المحرر','لقد تم تعيينك كمحرر لطلب التقديم الموجه إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>لقد تم تكليفك بطلب التقديم الآتي لمتابعته خلال عملية التحكيم المناظر.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>الملخص</b></p>{$submissionAbstract}<p>يرجى تسجيل الدخول <a href=\"{$submissionUrl}\">لمعاينة طلب التقديم</a> وتعيين المحكمين المؤهلين له. يمكنك تعيين المحكم عبر النقر على \"إضافة محكم\".</p><p>شكرًا مقدمًا.</p><p>أطيب التحايا،</p>{$signature}'),
(173,'EDITOR_ASSIGN_REVIEW','en','Assign Editor','You have been assigned as an editor on a submission to {$contextName}','<p>Dear {$recipientName},</p><p>The following submission has been assigned to you to see through the peer review process.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please login to <a href=\"{$submissionUrl}\">view the submission</a> and assign qualified reviewers. You can assign a reviewer by clicking \"Add Reviewer\".</p><p>Thank you in advance.</p><p>Kind regards,</p>{$signature}'),
(174,'EDITOR_ASSIGN_REVIEW','fr','Assigner un·e éditeur·rice','Vous avez été assigné.e en tant que rédacteur.trice d\'une soumission de la revue {$contextName}','<p>{$recipientName},</p><p>La soumission suivante vous a été assignée pour le processus d\'évaluation par les pairs.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Résumé</b></p>{$submissionAbstract}<p>Veuillez vous connecter pour <a href=\"{$submissionUrl}\">voir la soumission</a> et désigner des évaluateur.trice.s qualifié.es. Vous pouvez désigner un.e évaluateur.trice en cliquant sur « Ajouter un.e évaluateur.trice ».</p><p>Je vous remercie d\'avance.</p><p>Cordialement,</p>{$signature}'),
(175,'EDITOR_ASSIGN_PRODUCTION','ar','تعيين المحرر','لقد تم تعيينك كمحرر لطلب التقديم الموجه إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>لقد تم تكليفك بطلب التقديم الآتي لمتابعته خلال مرحلة الإنتاج.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>الملخص</b></p>{$submissionAbstract}<p>يرجى تسجيل الدخول <a href=\"{$submissionUrl}\">لمعاينة طلب التقديم</a>. بمجرد توافر الملفات الجاهزة للإنتاج، إرفعها من خلال مقطع <strong>الألواح الطباعية للإنتاج</strong>. بعدها قم بجدولة العمل للنشر عبر النقر على زر <strong>الجدولة للنشر</strong>.</p><p>شكرًا مقدمًا.</p><p>أطيب التحايا،</p>{$signature}'),
(176,'EDITOR_ASSIGN_PRODUCTION','en','Assign Editor','You have been assigned as an editor on a submission to {$contextName}','<p>Dear {$recipientName},</p><p>The following submission has been assigned to you to see through the production stage.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please login to <a href=\"{$submissionUrl}\">view the submission</a>. Once production-ready files are available, upload them under the <strong>Publication > Galleys</strong> section. Then schedule the work for publication by clicking the <strong>Schedule for Publication</strong> button.</p><p>Thank you in advance.</p><p>Kind regards,</p>{$signature}'),
(177,'EDITOR_ASSIGN_PRODUCTION','fr','Assigner un·e éditeur·rice','Vous avez été assigné.e en tant que rédacteur.trice d\'une soumission de la revue {$contextName}','<p>{$recipientName},</p><p>La soumission suivante vous a été assignée pour suivre le processus de production.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Résumé</b></p>{$submissionAbstract}<p>Veuillez vous connecter pour <a href=\"{$submissionUrl}\">afficher la soumission</a>. Une fois les fichiers prêts pour la production disponibles, les téléverser sous la section <strong>Publication &gt; Épreuves</strong>. Ensuite, planifier la publication en cliquant sur le bouton <strong>Planifier la publication</strong>.</p><p>Merci d\'avance.</p><p>Cordialement,</p>{$signature}'),
(178,'LAYOUT_REQUEST','ar','جاهز للإنتاج','طلب التقديم {$submissionId} صار جاهزًا لمرحلة الإنتاج من أجل {$contextAcronym}','<p>عزيزي {$recipientName}،</p><p>طلب تقديم جديد صار جاهزًا لتعديل إخراجه الطباعي:</p><p><a href=\"{$submissionUrl}\">{$submissionId} — {$submissionTitle}</a><br />{$contextName}</p><ol><li>. أنقر على رابط طلب التقديم أعلاه.</li><li>. قم بتنزيل الملفات الجاهزة للإنتاج واستعملها لإنشاء الألواح الطباعية بما يتناسب مع معايير المجلة.</li><li>.إرفع هذه الألواح إلى مقطع النشر العائد لطلب التقديم.</li><li>إستعمل مناقشات الإنتاج لإشعار المحرر بأن الألواح الطباعية صارت جاهزة.</li></ol><p>إذا تعذر عليك القيام بهذا العمل حاليًا أو كانت لديك أي أسئلة، أرجو التواصل معي. شكرًا لمساهمتك في هذه المجلة.</p><p>أطيب التحايا،</p>{$signature}'),
(179,'LAYOUT_REQUEST','en','Ready for Production','Submission {$submissionId} is ready for production at {$contextAcronym}','<p>Dear {$recipientName},</p><p>A new submission is ready for layout editing:</p><p><a href=\"{$submissionUrl}\">{$submissionId} — {$submissionTitle}</a><br />{$contextName}</p><ol><li>Click on the Submission URL above.</li><li>Download the Production Ready files and use them to create the galleys according to the journal\'s standards.</li><li>Upload the galleys to the Publication section of the submission.</li><li>Use the  Production Discussions to notify the editor that the galleys are ready.</li></ol><p>If you are unable to undertake this work at this time or have any questions, please contact me. Thank you for your contribution to this journal.</p><p>Kind regards,</p>{$signature}'),
(180,'LAYOUT_REQUEST','fr','Prêt à la production','La soumission {$submissionId} est prête pour production à la revue {$contextAcronym}','<p>Cher {$recipientName},</p><p>Une nouvelle soumission est prête pour la mise en page :</p><p><a href=\"{$submissionUrl}\">{$submissionId} — {$submissionTitle}</a><br />{$contextName}</p><ol><li>Cliquez sur l\'URL de la soumission ci-dessus.</li><li>Téléchargez les fichiers prêts pour la production et utilisez-les pour créer les épreuves conformément aux normes de la revue.</li><li>Téléchargez les épreuves dans la section Publication de la soumission.</li><li>Utilisez les Discussions de Production pour informer l\'éditeur que les épreuves sont prêtes.</li></ol><p>Si vous n\'êtes pas en mesure d\'effectuer ce travail en ce moment ou si vous avez des questions, veuillez nous contacter. Merci pour votre contribution à cette revue.</p><p>Cordialement,</p>{$signature}'),
(181,'LAYOUT_COMPLETE','ar','الألواح الطباعية مكتملة','التصميمات الطباعي إكتملت','<p>عزيزي {$recipientName}،</p><p>لقد تم تحضير الألواح الطباعية الخاصة بطلب التقديم الآتي وصارت جاهزة للمراجعة الأخيرة.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$contextName}</p><p>إن كانت لديكم أي استفسارات، أرجو التواصل معي.</p><p>أطيب التحايا،</p><p>{$senderName}</p>'),
(182,'LAYOUT_COMPLETE','en','Galleys Complete','Galleys Complete','<p>Dear {$recipientName},</p><p>Galleys have now been prepared for the following submission and are ready for final review.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$contextName}</p><p>If you have any questions, please contact me.</p><p>Kind regards,</p><p>{$signature}</p>'),
(183,'LAYOUT_COMPLETE','fr','Épreuves complétées','Mise en page des épreuves terminée','<p>Cher {$recipientName},</p><p>Les épreuves ont été préparées pour la soumission suivante et sont prêtes pour la révision finale.</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$contextName}</p><p>Si vous avez des questions, veuillez nous contacter.</p><p>Cordialement,</p><p>{$signature}</p>'),
(184,'VERSION_CREATED','ar','الإصدار تم إنشاؤه','تم إنشاء إصدار جديد من \"{$submissionTitle}\"','<p>عزيزي {$recipientName}، </p><p>هذه رسالة مؤتمتة لإبلاغكم بإنشاء نسخة جديدة من طلب تقديمكم، \"{$submissionTitle}\". بإمكانكم معاينة هذه النسخة من دفة قيادة طلب تقديمكم عبر الرابط الآتي:</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a></p><hr><p>هذه رسالة بريد الكتروني مؤتمتة مرسلة من <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(185,'VERSION_CREATED','en','Version Created','A new version was created for \"{$submissionTitle}\"','<p>Dear {$recipientName}, </p><p>This is an automated message to inform you that a new version of your submission, \"{$submissionTitle}\", was created. You can view this version from your submission dashboard at the following link:</p><p><a href=\"{$submissionUrl}\">\"{$submissionTitle}\"</a></p><hr><p>This is an automatic email sent from <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(186,'VERSION_CREATED','fr','Version créée','Une nouvelle version de {$submissionTitle} a été créée','<p>{$recipientName}, </p><p>Ceci est un courriel automatique de <a href=\"{$contextUrl}\">{$contextName}</a> pour vous informer qu\'une nouvelle version de votre soumission, « {$submissionTitle} », a été créée. Vous pouvez consulter cette version à partir de votre tableau de bord de soumission :</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a></p><hr><p>Ce courriel automatique a été envoyé par <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(187,'EDITORIAL_REMINDER','ar','تذكير هيئة التحرير','مهام التحرير المتميزة لـ {$contextName}','<p>عزيزنا {$recipientName}،</p><p>لقد تم تعيينكم حاليًا لتولي {$numberOfSubmissions} من طلبات التقديم في <a href=\"{$contextUrl}\">{$contextName}</a>. طلبات التقديم الآتية <b>بانتظار استجابتكم</b>.</p>{$outstandingTasks}<p>يمكنكم معاينة كل مهامكم في <a href=\"{$submissionsUrl}\">دفة قيادة طلب التقديم</a>.</p><p>إذا كانت لديكم أي استفسارات بشأن مهامكم، يرجى التواصل مع {$contactName} من خلال {$contactEmail}.</p>'),
(188,'EDITORIAL_REMINDER','en','Editorial Reminder','Outstanding editorial tasks for {$contextName}','<p>Dear {$recipientName},</p><p>You are currently assigned to {$numberOfSubmissions} submissions in <a href=\"{$contextUrl}\">{$contextName}</a>. The following submissions are <b>waiting for your response</b>.</p>{$outstandingTasks}<p>View all of your assignments in your <a href=\"{$submissionsUrl}\">submission dashboard</a>.</p><p>If you have any questions about your assignments, please contact {$contactName} at {$contactEmail}.</p>'),
(189,'EDITORIAL_REMINDER','fr','Rappel éditorial','Tâches éditoriales en attente pour {$contextName}','<p>{$recipientName},</p><p>Vous êtes actuellement en charge de {$numberOfSubmissions} soumissions dans <a href=\"{$contextUrl}\">{$contextName}</a>. Une <b>réponse de votre part</b> est attendue pour les soumissions suivantes.</p>{$outstandingTasks}<p>Vous pouvez consulter toutes vos soumissions dans votre <a href=\"{$submissionsUrl}\">tableau de bord des soumissions</a>.</p><p>Si vous avez des questions, veuillez contacter {$contactName} à l\'adresse {$contactEmail}.</p>'),
(190,'SUBMISSION_SAVED_FOR_LATER','ar','تم حفظ طلب التقديم لما بعد','استئناف طلب تقديمك إلى {$contextName}','<p>عزيزي {$recipientName}،</p><p>تفاصيل طلب تقديمكم قد تم حفظها في نظامنا، ولكنه لم يتم تقديمه للنظر فيه بعد. بإمكانكم العودة لإكمال طلب تقديمكم في أي وقت عبر الرابط أدناه.</p><p><a href=\"{$submissionWizardUrl}\">{$authorsShort} — \"{$submissionTitle}\"</a></p><hr><p>هذه رسالة مؤتمتة من <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(191,'SUBMISSION_SAVED_FOR_LATER','en','Submission Saved for Later','Resume your submission to {$contextName}','<p>Dear {$recipientName},</p><p>Your submission details have been saved in our system, but it has not yet been submitted for consideration. You can return to complete your submission at any time by following the link below.</p><p><a href=\"{$submissionWizardUrl}\">{$authorsShort} — \"{$submissionTitle}\"</a></p><hr><p>This is an automated email from <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(192,'SUBMISSION_SAVED_FOR_LATER','fr','Soumission incomplète sauvegardée','Reprenez votre soumission à {$contextName}','<p>{$recipientName},</p><p>Les détails de votre soumission ont été enregistrés, mais vous ne l\'avez pas encore finalisée. Vous pouvez le faire en cliquant sur le lien ci-dessous : </p><p><a href=\"{$submissionWizardUrl}\">{$authorsShort} — {$submissionTitle}</a></p><hr><p>Ceci est un message automatique de <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(193,'SUBMISSION_NEEDS_EDITOR','ar','طلب التقديم بحاجة إلى محرر','طلب تقديم جديد بحاجة إلى تعيين أحد المحررين له: \"{$submissionTitle}\"','<p>عزيزي {$recipientName}،</p><p>طلب التقديم الآتي قد تم تسليمه ولم يتكفل به أي محرر بعد.</p><p><a href=\"{$submissionUrl}\">\"{$submissionTitle}\"</a><br />{$authors}</p><p><b>الملخص</b></p>{$submissionAbstract}<p>يرجى تعيين المحرر الذي سيتولى مسؤولية متابعة طلب التقديم عبر النقر على العنوان أعلاه ثم تعيين المحرر من مقطع المساهمين.</p><hr><p>هذه رسالة مؤتمتة من <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(194,'SUBMISSION_NEEDS_EDITOR','en','Submission Needs Editor','A new submission needs an editor to be assigned: \"{$submissionTitle}\"','<p>Dear {$recipientName},</p><p>The following submission has been submitted and there is no editor assigned.</p><p><a href=\"{$submissionUrl}\">\"{$submissionTitle}\"</a><br />{$authors}</p><p><b>Abstract</b></p>{$submissionAbstract}<p>Please assign an editor who will be responsible for the submission by clicking the title above and assigning an editor under the Participants section.</p><hr><p>This is an automated email from <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(195,'SUBMISSION_NEEDS_EDITOR','fr','Un·e éditeur·rice est nécessaire pour la soumission','Un·e éditeur·rice doit être assigné·e à une nouvelle soumission : « {$submissionTitle} »','<p>{$recipientName},</p><p>La soumission suivante a été déposée :</p><p><a href=\"{$submissionUrl}\">{$submissionTitle}</a><br />{$authors}</p><p><b>Résumé</b></p>{$submissionAbstract}<p>Veuillez désigner un·e éditeur·rice qui sera responsable de cette soumission en cliquant sur le titre ci-dessus et en choisissant un·e éditeur·rice dans la section Participants.</p><hr><p>Ceci est un courriel automatique de <a href=\"{$contextUrl}\">{$contextName}</a>.</p>'),
(196,'PAYMENT_REQUEST_NOTIFICATION','ar','إلتماس الدفع المالي','إشعار إلتماس الدفع','<p>عزيزي {$recipientName}،</p><p>تهانينا على قبول طلب تقديمك، {$submissionTitle}، الموجه إلى {$contextName}. طالما قد حصل القبول، نرغب أن نطالبك بتسديد رسم النشر.</p><p>هذا الرسم يغطي تكاليف الإنتاج المتربة على إيصال طلب تقديمك إلى النشر. لإجراء الدفع المالي، يرجى زيارة <a href=\"{$queuedPaymentUrl}\">{$queuedPaymentUrl}</a>.</p><p>إذا كانت لديك أي استفسارات، راجع لطفًا <a href=\"{$submissionGuidelinesUrl}\">إرشادات التقديم</a></p>'),
(197,'PAYMENT_REQUEST_NOTIFICATION','en','Payment Request','Payment Request Notification','<p>Dear {$recipientName},</p><p>Congratulations on the acceptance of your submission, {$submissionTitle}, to {$contextName}. Now that your submission has been accepted, we would like to request payment of the publication fee.</p><p>This fee covers the production costs of bringing your submission to publication. To make the payment, please visit <a href=\"{$queuedPaymentUrl}\">{$queuedPaymentUrl}</a>.</p><p>If you have any questions, please see our <a href=\"{$submissionGuidelinesUrl}\">Submission Guidelines</a></p>'),
(198,'PAYMENT_REQUEST_NOTIFICATION','fr','Demande de paiement','Avis de demande de paiement','<p>Bonjour {$recipientName},</p><p>Félicitations pour l\'acceptation de votre texte, {$submissionTitle}, dans {$contextName}. Maintenant que votre texte a été accepté, il est nécessaire de payer les frais de publication afin de compléter le processus.</p><p>Ces frais couvrent les coûts de production permettant d\'assurer la publication de votre texte. Pour effectuer le paiement, rendez-vous sur <a href=\"{$queuedPaymentUrl}\">{$queuedPaymentUrl}</a>.</p><p> Si vous avez des questions, référez-vous à nos <a href=\"{$submissionGuidelinesUrl}\">directives de soumissions</a>.</p>'),
(199,'CHANGE_EMAIL','ar','تغيير دعوة البريد الالكتروني','تأكيد طلب تغيير عنوان البريد الالكتروني لجهة المراسلة','<p>عزيزي {$recipientName}،</p><p>أنت تتلقى هذا البريد الالكتروني لأن أحد ما طلب تغيير عنوان بريدك الالكتروني إلى {$newEmail}.</p><p>إذا كنت أنت من قدم هذا الطلب، يرجى <a href=\"{$acceptInvitationUrl}\">تأكيد</a> هذا التغيير.</p><p>بإمكانك دائمًا <a href=\"{$declineInvitationUrl}\">رفض</a> هذا التغيير في البريد الالكتروني.</p><p>أرجو أن لا تتردد في مراسلتي بشأن أي استفسارات عن طلب التقديم أو عملية التحكيم.</p><p>أطيب التحايا،</p>{$siteContactName}'),
(200,'CHANGE_EMAIL','en','Change Email Address Invitation','Confirm account contact email change request','<p>Dear {$recipientName},</p><p>You are receiving this email because someone has requested a change of your email to {$newEmail}.</p><p>If you have made this request please <a href=\"{$acceptInvitationUrl}\">confirm</a> the email change.</p><p>You can always <a href=\"{$declineInvitationUrl}\">reject</a> this email change.</p><p>Please feel free to contact me with any questions about the submission or the review process.</p><p>Kind regards,</p>{$siteContactName}'),
(201,'CHANGE_EMAIL','fr','Modifier l\'adresse e-mail d\'invitation','Confirmer la demande de modification de l\'adresse e-mail de contact du compte','<p>Bonjour {$recipientName},</p><p>Vous recevez ce courriel car nous avons reçu une demande de modification de votre adresse de courriel par {$newEmail}.</p><p>Si vous êtes à l\'origine de cette demande, merci de <a href=\"{$acceptInvitationUrl}\">confirmer</a> ce changement.</p><p>Sinon, merci de <a href=\"{$declineInvitationUrl}\">refuser</a> ce changement.</p><p>N\'hésitez pas à nous contacter pour toute question au sujet de la soumission et du processus d\'évaluation. </p><p>Bien cordialement,</p>{$siteContactName}'),
(202,'ORCID_COLLECT_AUTHOR_ID','ar','تجميع معرف المؤلف من orcid','تقديم ORCID','>عزيزنا {$recipientName}،<br/>\n<br/>\nلقد تم إدراجك بمثابة مؤلف مشارك في عمل مقدم إلى {$contextName}.<br/>\nلتأكيد مصادقتك، لطفاً، أضف رمزك التعريفي في ORCID إلى طلب التقديم هذا عبر زيارة الرابط أدناه.<br/>\n<br/>\n<a href=\"{$authorOrcidUrl}\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/sites/default/files/images/orcid_wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"ORCID iD icon\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>إفتح حساباً أو ضع رمزك في ORCID</a><br/>\n<br/>\n<br/>\n<a href=\"{$orcidAboutUrl}\">المزيد مع المعلومات عن ORCID في {$contextName}</a><br/>\n<br/>\nإذا كانت لديك أي استفسارات، رجاءً، لا تتردد في مراسلتي.<br/>\n<br/>\n{$principalContactSignature}<br/>\n'),
(203,'ORCID_COLLECT_AUTHOR_ID','en','orcidCollectAuthorId','Submission ORCID','Dear {$recipientName},<br/>\n<br/>\nYou have been listed as an author on a manuscript submission to {$contextName}.<br/>\nTo confirm your authorship, please add your ORCID id to this submission by visiting the link provided below.<br/>\n<br/>\n<a href=\"{$authorOrcidUrl}\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"ORCID iD icon\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>Register or connect your ORCID iD</a><br/>\n<br/>\n<br>\n<a href=\"{$orcidAboutUrl}\">More information about ORCID at {$contextName}</a><br/>\n<br/>\nIf you have any questions, please contact me.<br/>\n<br/>\n{$principalContactSignature}<br/>\n'),
(204,'ORCID_COLLECT_AUTHOR_ID','fr','orcidCollectAuthorId','Soumission ORCID','{$recipientName},<br/>\n<br/>\nVous avez été inscrit ou inscrite en tant qu\'auteur ou autrice pour un manuscrit soumis à {$contextName}.<br/>\nPour confirmer votre statut d\'auteur ou d\'autrice, veuillez ajouter votre identifiant ORCID à cette soumission en cliquant sur le lien ci-dessous.<br/>\n<br/>\n<a href=\"{$authorOrcidUrl}\"><img id=\"orcid-id-logo\" src=\"https ://orcid.org/sites/default/files/images/orcid_16x16.png\" width=\'16\' height=\'16\' alt=\"icône identifiant ORCID\" style=\"display : block ; margin : 0 .5em 0 0 ; padding : 0 ; float : left ;\"/>Créez ou connectez-vous avec votre identifiant ORCID</a><br/>\n<br/>\n<br/>\n<a href=\"{$orcidAboutUrl}\">Plus de renseignements sur votre identifiant ORCID dans {$contextName}</a><br/>\n<br/>\nSi vous avez des questions, n\'hésitez pas à nous contacter.<br/>\n<br/>\n{$principalContactSignature}<br/>\n'),
(205,'ORCID_REQUEST_AUTHOR_AUTHORIZATION','ar','إلتماس تفويض المؤلف من orcid','إلتماس الوصو إلى حساب ORCID','عزيزنا {$recipientName}،<br>\n<br>\nلقد تم إدراجك بمثابة مؤلف مشارك في العمل الموسوم \"{$submissionTitle}\" والمقدم إلى {$contextName}.\n<br>\n<br>\nنلتمس منح الموافقة على إضافة رمزك في ORCID إلى طلب التقديم هذا وكذلك إضافة هذا الطلب إلى ملفك الشخصي في ORCID عند النشر.<br>\nقم بزيارة الرابط الرسمي لموقع ORCID، وسجل دخولك فيه ثم أجرِ ما يلزم لتفويضنا عبر اتباع التعليمات الآتية:<br>\n<a href=\"{$authorOrcidUrl}\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/sites/default/files/images/orcid_wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"إيقونة رمز ORCID\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>إفتح حساباً أو ضع رمزك في ORCID</a><br/>\n<br>\n<br>\n<a href=\"{$orcidAboutUrl}\">المزيد مع المعلومات عن ORCID في {$contextName}</a><br/>\n<br>\nإذا كانت لديك أي استفسارات، رجاءً، لا تتردد في مراسلتي.<br>\n<br>\n{$principalContactSignature}<br>\n'),
(206,'ORCID_REQUEST_AUTHOR_AUTHORIZATION','en','orcidRequestAuthorAuthorization','Requesting ORCID record access','Dear {$recipientName},<br>\n<br>\nYou have been listed as an author on the manuscript submission \"{$submissionTitle}\" to {$contextName}.\n<br>\n<br>\nPlease allow us to add your ORCID id to this submission and also to add the submission to your ORCID profile on publication.<br>\nVisit the link to the official ORCID website, login with your profile and authorize the access by following the instructions.<br>\n<br>\n<a href=\"{$authorOrcidUrl}\" style=\"display: inline-flex; align-items: center; background-color: white; text-align: center; padding: 10px 20px; text-decoration: none; border-radius: 5px; border: 2px solid #d7d4d4;\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"ORCID iD icon\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>Register or Connect your ORCID iD</a><br/>\n<br>\n<br>\nClick here to verify your account with ORCID: <a href=\"{$authorOrcidUrl}\">{$authorOrcidUrl}.</a>\n<br>\n<br>\n<a href=\"{$orcidAboutUrl}\">More about ORCID at {$contextName}</a><br/>\n<br>\n<br>\nIf you have any questions, please contact me.<br>\n<br>\n{$principalContactSignature}<br>\n'),
(207,'ORCID_REQUEST_AUTHOR_AUTHORIZATION','fr','orcidRequestAuthorAuthorization','Demande d\'accès au dossier ORCID','{$recipientName},<br/>\n<br/>\nVous avez été inscrit ou inscrite en tant qu\'auteur ou autrice pour le manuscrit « {$submissionTitle} » soumis à {$contextName}.\n<br/>\n<br/>\nVeuillez nous autoriser à ajouter votre identifiant ORCID à cette soumission et à ajouter également la soumission à votre dossier ORCID suite à sa publication.\n<br/>\nSuivez le lien vers le site officiel d\'ORCID, connectez-vous avec votre profil et autorisez l\'accès en suivant les instructions.<br/>\n<a href=\"{$authorOrcidUrl}\"><img id=\"orcid-id-logo\" src=\"https://orcid.org/sites/default/files/images/orcid_16x16.png\" width=\'16\' height=\'16\' alt=\"icône identifiant ORCID\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>Créez ou connectez-vous avec votre identifiant ORCID</a><br/>\n<br/>\n<br/>\n<a href=\"{$orcidAboutUrl}\">Plus de renseignements sur votre identifiant ORCID dans {$contextName}</a>\n<br/>\n<br/>\nSi vous avez des questions, n\'hésitez pas à nous contacter.<br/>\n<br/>\nBien cordialement,\n<br/>\n{$principalContactSignature}<br/>\n'),
(208,'USER_ROLE_ASSIGNMENT_INVITATION','ar','إشعار دعوة المستخدم إلى الدور','أنت مدعو إلى أدوار جديدة','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>دعوة إلى دور جديد</h2>    </div>    <div class=\'email-content\'>        <p>عزيزي {$recipientName}،</p>        <p>في ضوء خبرتكم، قد تمت دعوتك من قبل {$inviterName} لتولي أدوار جديدة في {$contextName}</p>        <p>في {$contextName}، نحن نقدر خصوصيتك. لذلك اتخذنا الخطوات التي تضمن إمتثالنا للائحة أمن البيانات GDPR. تلك الخطوات تتضمن كونك مسؤول عن إدخال بياناتك ومختار لمن يمكنه معاينة تلك المعلومات. للمزيد من المعلومات عن كيفية معالجتنا لبياناتك، يرجى الرجوع إلى سياسة الخصوصية العائدة لنا.</p>        <div>{$existingRoles}</div>        <div>{$rolesAdded}</div>        <p>عند قبولك للدعوة، ستتم إعادة توجيهك إلى {$contextName}.</p>        <p>Fلا تتردد في مراسلتي بشأن أي أسئلة قد تطرأ عندك بشأن هذه العملية.</p>        <table class=\'btn-wrap\' role=\'presentation\' border=\'0\' cellpadding=\'0\' cellspacing=\'10\'>            <tr><td class=\'btn-cell btn-accept\'  bgcolor=\'#28a745\'><a class=\'btn\' href=\'{$acceptUrl}\'>قبول الدعوة</a></td></tr>            <tr><td class=\'btn-cell btn-decline\' bgcolor=\'#dc3545\'><a class=\'btn\' href=\'{$declineUrl}\'>رفض الدعوة</a></td></tr>        </table>        <p>أطيب التحايا،</p>        <p>{$contextName}</p>    </div></div><style>{$emailTemplateStyle}</style>'),
(209,'USER_ROLE_ASSIGNMENT_INVITATION','en','User Invited to Role Notification','You are invited to new roles','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>Invitation to New Role</h2>    </div>    <div class=\'email-content\'>        <p>Dear {$recipientName},</p>        <p>In light of your expertise, you have been invited by {$inviterName} to take on new roles at {$contextName}</p>        <p>At {$contextName}, we value your privacy. As such, we have taken steps to ensure that we are fully GDPR compliant. These steps include you being accountable to enter your own data and choosing who can see what information. For additional information on how we handled your data, please refer to our Privacy Policy.</p>        <div>{$existingRoles}</div>        <div>{$rolesAdded}</div>        <p>On accepting the invite, you will be redirected to {$contextName}.</p>        <p>Feel free to contact me with any questions about the process.</p>        <table class=\'btn-wrap\' role=\'presentation\' border=\'0\' cellpadding=\'0\' cellspacing=\'10\'>            <tr><td class=\'btn-cell btn-accept\'  bgcolor=\'#28a745\'><a class=\'btn\' href=\'{$acceptUrl}\'>Accept Invitation</a></td></tr>            <tr><td class=\'btn-cell btn-decline\' bgcolor=\'#dc3545\'><a class=\'btn\' href=\'{$declineUrl}\'>Decline Invitation</a></td></tr>        </table>        <p>Kind regards,</p>        <p>{$contextName}</p>    </div></div>'),
(210,'USER_ROLE_ASSIGNMENT_INVITATION','fr','Notification d\'invitation à un rôle','Un nouveau rôle vous a été attribué','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>Invitation à un nouveau rôle</h2>    </div>    <div class=\'email-content\'>        \n<p>Bonjour {$recipientName},</p>        \n<p>Au regard de votre expertise, vous êtes invité/e par {$inviterName} pour intervenir auprès de {$contextName}</p>        \n<p>Concernant la protection de vos données, pour garantir la pleine conformité au RGPD, vous êtes responsables de la saisie de vos données personnelles et vous choisissez qui peut les consulter. Pour plus d\'informations sur la manière dont vos données sont traitées, veuillez consulter la Politique de confidentialité.</p>        <div>{$existingRoles}</div>        <div>{$rolesAdded}</div>        \n<p>En acceptant cette invitation, vous serez redirigé/e vers {$contextName}.</p>        \n<p>N\'hésitez pas à nous contacter pour toute question.</p>        \n<table class=\'btn-wrap\' role=\'presentation\' border=\'0\' cellpadding=\'0\' cellspacing=\'10\'>            <tr><td class=\'btn-cell btn-accept\'  bgcolor=\'#28a745\'><a class=\'btn\' href=\'{$acceptUrl}\'>Accepter l\'invitation</a></td></tr>            <tr><td class=\'btn-cell btn-decline\' bgcolor=\'#dc3545\'><a class=\'btn\' href=\'{$declineUrl}\'>Décliner l\'invitation</a></td></tr>        </table>        <p>Bien cordialement,</p>        <p>{$contextName}</p>    </div></div>'),
(211,'USER_ROLE_END','ar','إشعار إنتهاء دور المستخدم','لقد تمت إزالتك من دور ما','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>أُزلت من الدور</h2>    </div>    <div class=\'email-content\'>        <p>عزيزي {$recipientName}،</p>        <p>شكرًا جزيلاً على مساهمتك في دور {$roleRemoved} في {$contextName}.</p>        <p>هذا إشعار لإبلاغك بأنه قد تمت إزالتك من الدور الآتي في {$contextName}: <b>{$roleRemoved}</b>.</p>        <p>لا يزال حسابك في {$contextName} فعالاً وأي أدوار أخرى كانت لديك سابقًا فيها لا تزال فعالة أيضًا.</p>        <p>لا تتردد في مراسلتي بشأن أي أسئلة عن هذه العملية.</p>        <p>أطيب التحايا،</p>        <p>{$contextName}</p>    </div></div><style>{$emailTemplateStyle}</style>'),
(212,'USER_ROLE_END','en','User Role Ended Notification','You have been removed from a role','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>Removed from a Role</h2>    </div>    <div class=\'email-content\'>        <p>Dear {$recipientName},</p>        <p>Thank you very much for your participation in the role of {$roleRemoved} at {$contextName}.</p>        <p>This is a notice to let you know that you have been removed from the following role at {$contextName}: <b>{$roleRemoved}</b>.</p>        <p>Your account with {$contextName} is still active and any other roles you previously held are still active.</p>        <p>Feel free to contact me with any questions about the process.</p>        <p>Kind regards,</p>        <p>{$contextName}</p>    </div></div>'),
(213,'USER_ROLE_END','fr','Notification de fin de rôle utilisateur','Vous avez été supprimé d\'un rôle','<div class=\'email-container\'><div class=\'email-header\'>        <h2>Retrait d\'un rôle</h2>    </div>    <div class=\'email-content\'>        <p>Bonjour {$recipientName},</p>        \n<p>Nous vous remercions pour votre collaboration en tant que {$roleRemoved} pour {$contextName}.</p>\n<p>Ce message vous informe que le rôle de {$roleRemoved} ne vous est désormais plus attribué. </p>\n<p>Votre compte pour {$contextName} est cependant toujours actif ainsi que vos autres rôles.</p>\n<p>N\'hésitez pas à nous contacter pour toute question.</p>        \n<p>Bien cordialement,</p>        \n<p>{$contextName}</p>    </div></div>'),
(214,'USER_ROLE_MASTHEAD_UPDATE','ar','','',''),
(215,'USER_ROLE_MASTHEAD_UPDATE','en','User Role Masthead Visibility Update Notification','Your journal masthead visibility has been updated','<div class=\'email-container\'>    <div class=\'email-header\'>        <h2>Updated role masthead visibility</h2>    </div>    <div class=\'email-content\'>        <p>Dear {$recipientName},</p>        <p>Your journal masthead visibility for the role {$roleNameAndDates} in {$contextName} has been updated.</p>        <p>New setting: {$appearOnMasthead}</p>        <p>If you have questions about this change, please contact the journal manager.</p>        <p>Kind regards,</p>        <p>{$contextName}</p>    </div></div>'),
(216,'USER_ROLE_MASTHEAD_UPDATE','fr','','',''),
(217,'ORCID_REQUEST_UPDATE_SCOPE','ar','إلتماس تحديث نطاق orcid','إلتماس وصول محدث إلى سجلات ORCID','عزيزي {$recipientName}،<br>\n<br>\nأنت مدرج كمساهم (مؤلف أو محكم) في نص طلب التقديم الموسوم \"{$submissionTitle}\" المقدم إلى {$contextName}.\n<br>\n<br>\nلقد سبق لك وأن رخصت {$contextName} بإدراج مُعرَّفِك في ORCID في الموقع، ونحن نلتمس صلاحيات محدثة لإضافة مساهمتك إلى ملفك الشخصي في ORCID.<br>\nقم بزيارة الرابط المؤدي إلى موقع ORCID الرسمي، قم بتسجيل الدخول إلى حسابك فيه وقم بترخيص الوصول عبر اتباع التوجيهات الآتية.<br>\n<br>\n<a href=\"{$authorOrcidUrl}\" style=\"display: inline-flex; align-items: center; background-color: white; text-align: center; padding: 10px 20px; text-decoration: none; border-radius: 5px; border: 2px solid #d7d4d4;\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"أيقونة مُعرَّف ORCID\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>التسجيل أو ربط مُعرَّفك في ORCID </a><br/>\n<br>\n<br>\nأنقر هنا لتحديث حسابك مع ORCID: <a href=\"{$authorOrcidUrl}\">{$authorOrcidUrl}.</a>\n<br>\n<br>\n<a href=\"{$orcidAboutUrl}\">المزيد عن ORCID في {$contextName}</a><br/>\n<br>\n<br>\nإذا كانت لديك أي أسئلة، يرجى التواصل معي.<br>\n<br>\n{$principalContactSignature}<br>\n'),
(218,'ORCID_REQUEST_UPDATE_SCOPE','en','orcidRequestUpdateScope','Requesting updated ORCID record access','Dear {$recipientName},<br>\n<br>\nYou are listed as a contributor (author or reviewer) on the manuscript submission \"{$submissionTitle}\" to {$contextName}.\n<br>\n<br>\nYou have previously authorized {$contextName} to list your ORCID id on the site, and we require updateded permissions to add your contribution to your ORCID profile.<br>\nVisit the link to the official ORCID website, login with your profile and authorize the access by following the instructions.<br>\n<br>\n<a href=\"{$authorOrcidUrl}\" style=\"display: inline-flex; align-items: center; background-color: white; text-align: center; padding: 10px 20px; text-decoration: none; border-radius: 5px; border: 2px solid #d7d4d4;\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"ORCID iD icon\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>Register or Connect your ORCID iD</a><br/>\n<br>\n<br>\nClick here to update your account with ORCID: <a href=\"{$authorOrcidUrl}\">{$authorOrcidUrl}.</a>\n<br>\n<br>\n<a href=\"{$orcidAboutUrl}\">More about ORCID at {$contextName}</a><br/>\n<br>\n<br>\nIf you have any questions, please contact me.<br>\n<br>\n{$principalContactSignature}<br>\n'),
(219,'ORCID_REQUEST_UPDATE_SCOPE','fr','orcidRequestUpdateScope','Demande de mise à jour de l\'accès à ORCID','Bonjour {$recipientName},<br>\n<br>\nVous êtes un/e contributeur/ice (auteur/ice ou évaluteur/ice) pour la soumission \"{$submissionTitle}\" de {$contextName}.\n<br>\n<br>\n<p>Vous avez précédemment autorisé {$contextName} à afficher votre ORCID sur le site, et nous avons besoin de votre permission pour que cette contribution soit ajoutée à votre profil ORCID.</p>\n<br>\nVeuillez vous rendre sur le site d\'ORCID, vous connecter à votre profil et autoriser l\'accès en suivant les instructions.\n<br>\n<br>\n<a href=\"{$authorOrcidUrl}\" style=\"display: inline-flex; align-items: center; background-color: white; text-align: center; padding: 10px 20px; text-decoration: none; border-radius: 5px; border: 2px solid #d7d4d4;\"><img id=\"orcid-id-logo\" src=\"https://info.orcid.org/wp-content/uploads/2020/12/ORCIDiD_icon16x16.png\" width=\'16\' height=\'16\' alt=\"ORCID iD icon\" style=\"display: block; margin: 0 .5em 0 0; padding: 0; float: left;\"/>S\'inscrire ou se connecter à ORCID</a><br/>\n<br>\n<br>\nCliquez ici pour mettre à jour votre compte sur ORCID :  <a href=\"{$authorOrcidUrl}\">{$authorOrcidUrl}.</a>\n<br>\n<br>\n<a href=\"{$orcidAboutUrl}\">Plus d\'informations sur ORCID : {$contextName}</a><br/>\n<br>\n<br>\nN\'hésitez pas à nous contacter pour toute question.\n<br>\nBien cordialement,\n<br>\n{$principalContactSignature}<br>\n'),
(220,'MANUAL_PAYMENT_NOTIFICATION','ar','إشعار الدفع اليدوي','إشعار الدفع اليدوي','عملية دفع يدوي بحاجة إلى معالجتها تخص المجلة {$contextName} والمستخدم &quot;{$senderUsername}&quot;.<br />\n<br />\nالفقرة التي في النية دفع المال لها هي &quot;{$paymentName}&quot;.<br />\nالكلفة هي {$paymentAmount} ({$paymentCurrencyCode}).<br />\n<br />\nتم إنشاء رسالة البريد الالكتروني هذه من قبل إضافة الدفع المالي اليدوي لنظام المجلات المفتوحة.'),
(221,'MANUAL_PAYMENT_NOTIFICATION','en','Manual Payment Notify','Manual Payment Notification','A manual payment needs to be processed for the journal {$contextName} and the user &quot;{$senderUsername}&quot;.<br />\n<br />\nThe item being paid for is &quot;{$paymentName}&quot;.<br />\nThe cost is {$paymentAmount} ({$paymentCurrencyCode}).<br />\n<br />\nThis email was generated by Open Journal Systems\' Manual Payment plugin.'),
(222,'MANUAL_PAYMENT_NOTIFICATION','fr','Avis de paiement manuel','Notification de paiement manuel','Un paiement manuel doit être traité pour la revue {$contextName} et l\'utilisateur ou utilisatrice {$senderName} (nom d\'utilisateur ou d\'utilisatrice &quot;{$senderUsername}&quot;).<br />\n<br />\nL\'élément facturé est &quot;{$paymentName}&quot;.<br />\nLe coût est de {$paymentAmount} ({$paymentCurrencyCode}).<br />\n<br />\nCe courriel a été généré par le module de paiement manuel d\'Open Journal Systems.');
